public static class Bool2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in bool2 v)
	{
		bw.Write(v.flags);	}

	public static bool2 Read2D_Boolean(this BinaryReader br)
	{
        return new bool2(br.ReadByte());	}
}


