	// TryParse variant

	public static bool TryParse(string s, out byte2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = byte.TryParse(nums[0], out byte x);
		var parsed_y = byte.TryParse(nums[1], out byte y);

        if(parsed_x && parsed_y)
        {
            val = new byte2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    
