public static class Byte2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in byte2 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
				}

	public static byte2 Read2D_Byte(this BinaryReader br)
	{
        		return new byte2( br.ReadByte(),  br.ReadByte() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static byte2 Select(this bool2 mask, in byte2 onTrue, in byte2 onFalse) => new byte2(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static byte MinComponent(in byte2 v)
	{
		return Min(v.x,v.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static byte MaxComponent(in byte2 v)
	{
		return Max(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in byte2 v)
	{
		return MaxIndex(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static byte2 Min(params byte2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static byte2 Max(params byte2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in byte2 a, in byte2 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in byte2 a, in byte2 b, byte epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static byte DistanceSqr(in byte2 a, in byte2 b)
		{
			return (byte)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in byte2 a, in byte2 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static byte2 Lerp(in byte2 from, in byte2 to, float lerp)
			{
				return new byte2( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp));
			}

            public static byte2 LerpUnclamped(in byte2 from, in byte2 to, float lerp)
			{
				return new byte2( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp));
			}
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct ushort2 : IVector<ushort>, IEquatable<ushort2>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 2;
    public static readonly Type BASE_TYPE = typeof(ushort);
	public const string BASE_TYPENAME = "System.UInt16";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const ushort COMPONENT_RATIO = 1 / (ushort)2;

	public static ushort2 Zero => new ushort2(0,0);
	public static ushort2 One => new ushort2(1,1);

		public static ushort2 MinValue => new ushort2(ushort.MinValue,ushort.MinValue);
		public static ushort2 MaxValue => new ushort2(ushort.MaxValue,ushort.MaxValue);

    
    
	

			        public readonly ushort x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ushort X => x;

	    		        public readonly ushort y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ushort Y => y;

	                 

	public readonly ushort this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				
				default: return default;
			}
		}
	}

    public readonly ushort GetElement(int index) => this[index];

    public readonly ushort GetElement(Axis2D axis) => this[(int)axis];

	public ushort2 SetComponent(ushort value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new ushort2(value,y);				
				case 1:
					return new ushort2(x,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public ushort2 SetX(ushort value) => SetComponent(value, 0);

                public ushort2 SetY(ushort value) => SetComponent(value, 1);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (ushort)MathX.AvgComponent(this);
            return new ushort2(c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new ushort2(c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(ushort);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public ushort2(ushort x = default(ushort), ushort y = default(ushort))
	{
    
				        this.x = x;
		    		        this.y = y;
		    	}

	public ushort2(ushort2 xy)
	{
        this = xy;
