	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "ushort2"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral()})";
    }

    
	public static ushort2 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new ushort2( ushort.Parse(nums[0]), ushort.Parse(nums[1]));
	}

    
	public static ushort2 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new ushort2( ushort.Parse(nums[0], provider), ushort.Parse(nums[1], provider));
	}

	public static ushort2 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new ushort2( ushort.Parse(nums[0], style), ushort.Parse(nums[1], style));
	}

	public static ushort2 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new ushort2( ushort.Parse(nums[0], style, provider), ushort.Parse(nums[1], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out ushort2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ushort.TryParse(nums[0], out ushort x);
		var parsed_y = ushort.TryParse(nums[1], out ushort y);

        if(parsed_x && parsed_y)
        {
            val = new ushort2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out ushort2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ushort.TryParse(nums[0], numberStyles, formatProvider, out ushort x);
		var parsed_y = ushort.TryParse(nums[1], numberStyles, formatProvider, out ushort y);

        if(parsed_x && parsed_y)
        {
            val = new ushort2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    

