		[MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly ushort2 Mask(bool2 mask, ushort masked = default(ushort)) => new ushort2(mask.x ? x : masked, mask.y ? y : masked);

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly ushort2 Mask(bool2 mask, in ushort2 masked) => new ushort2(mask.x ? x : masked.x, mask.y ? y : masked.y);

        
