public static class Ushort2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in ushort2 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
				}

	public static ushort2 Read2D_UInt16(this BinaryReader br)
	{
        		return new ushort2( br.ReadUInt16(),  br.ReadUInt16() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ushort2 Select(this bool2 mask, in ushort2 onTrue, in ushort2 onFalse) => new ushort2(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort MinComponent(in ushort2 v)
	{
		return Min(v.x,v.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort MaxComponent(in ushort2 v)
	{
		return Max(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in ushort2 v)
	{
		return MaxIndex(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort2 Min(params ushort2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort2 Max(params ushort2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in ushort2 a, in ushort2 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in ushort2 a, in ushort2 b, ushort epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static ushort DistanceSqr(in ushort2 a, in ushort2 b)
		{
			return (ushort)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in ushort2 a, in ushort2 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static ushort2 Lerp(in ushort2 from, in ushort2 to, float lerp)
			{
				return new ushort2( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp));
			}

            public static ushort2 LerpUnclamped(in ushort2 from, in ushort2 to, float lerp)
			{
				return new ushort2( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp));
			}
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct uint2 : IVector<uint>, IEquatable<uint2>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 2;
    public static readonly Type BASE_TYPE = typeof(uint);
	public const string BASE_TYPENAME = "System.UInt32";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const uint COMPONENT_RATIO = 1 / (uint)2;

	public static uint2 Zero => new uint2(0,0);
	public static uint2 One => new uint2(1,1);

		public static uint2 MinValue => new uint2(uint.MinValue,uint.MinValue);
		public static uint2 MaxValue => new uint2(uint.MaxValue,uint.MaxValue);

    
    
	

			        public readonly uint x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly uint X => x;

	    		        public readonly uint y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly uint Y => y;

	                 

	public readonly uint this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				
				default: return default;
			}
		}
	}

    public readonly uint GetElement(int index) => this[index];

    public readonly uint GetElement(Axis2D axis) => this[(int)axis];

	public uint2 SetComponent(uint value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new uint2(value,y);				
				case 1:
					return new uint2(x,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public uint2 SetX(uint value) => SetComponent(value, 0);

                public uint2 SetY(uint value) => SetComponent(value, 1);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (uint)MathX.AvgComponent(this);
            return new uint2(c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new uint2(c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(uint);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public uint2(uint x = default(uint), uint y = default(uint))
	{
    
				        this.x = x;
		    		        this.y = y;
		    	}

	public uint2(uint2 xy)
	{
        this = xy;
	}

	
	
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float2 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float2.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float2)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float2 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float2.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float2)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
