	}

    
	// TryParse variant

	public static bool TryParse(string s, out uint2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = uint.TryParse(nums[0], out uint x);
		var parsed_y = uint.TryParse(nums[1], out uint y);

        if(parsed_x && parsed_y)
        {
            val = new uint2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out uint2 val)
