			val = default;
			return false;
		}

        var parsed_x = uint.TryParse(nums[0], numberStyles, formatProvider, out uint x);
		var parsed_y = uint.TryParse(nums[1], numberStyles, formatProvider, out uint y);

        if(parsed_x && parsed_y)
        {
            val = new uint2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    

