public static class Uint2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in uint2 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
				}

	public static uint2 Read2D_UInt32(this BinaryReader br)
	{
        		return new uint2( br.ReadUInt32(),  br.ReadUInt32() ); 	}
}


