	{
		return MaxIndex(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint2 Min(params uint2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint2 Max(params uint2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in uint2 a, in uint2 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y);
	}

