[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct ulong2 : IVector<ulong>, IEquatable<ulong2>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 2;
    public static readonly Type BASE_TYPE = typeof(ulong);
	public const string BASE_TYPENAME = "System.UInt64";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const ulong COMPONENT_RATIO = 1 / (ulong)2;

	public static ulong2 Zero => new ulong2(0,0);
	public static ulong2 One => new ulong2(1,1);

		public static ulong2 MinValue => new ulong2(ulong.MinValue,ulong.MinValue);
		public static ulong2 MaxValue => new ulong2(ulong.MaxValue,ulong.MaxValue);

    
    
	

			        public readonly ulong x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong X => x;

	    		        public readonly ulong y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong Y => y;

	                 

	public readonly ulong this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				
				default: return default;
			}
		}
	}

    public readonly ulong GetElement(int index) => this[index];

    public readonly ulong GetElement(Axis2D axis) => this[(int)axis];

	public ulong2 SetComponent(ulong value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new ulong2(value,y);				
				case 1:
					return new ulong2(x,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public ulong2 SetX(ulong value) => SetComponent(value, 0);

                public ulong2 SetY(ulong value) => SetComponent(value, 1);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (ulong)MathX.AvgComponent(this);
            return new ulong2(c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new ulong2(c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(ulong);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public ulong2(ulong x = default(ulong), ulong y = default(ulong))
	{
    
				        this.x = x;
		    		        this.y = y;
		    	}

	public ulong2(ulong2 xy)
	{
        this = xy;
	}

	
	
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float2 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float2.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float2)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float2 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float2.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float2)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
