	public static bool TryParse(string s, out ulong2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ulong.TryParse(nums[0], out ulong x);
		var parsed_y = ulong.TryParse(nums[1], out ulong y);

        if(parsed_x && parsed_y)
        {
            val = new ulong2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    
