public static class Short2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in short2 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
				}

	public static short2 Read2D_Int16(this BinaryReader br)
	{
        		return new short2( br.ReadInt16(),  br.ReadInt16() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static short2 Select(this bool2 mask, in short2 onTrue, in short2 onFalse) => new short2(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short MinComponent(in short2 v)
	{
		return Min(v.x,v.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short MaxComponent(in short2 v)
	{
		return Max(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in short2 v)
	{
		return MaxIndex(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short2 Min(params short2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short2 Max(params short2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in short2 a, in short2 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in short2 a, in short2 b, short epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static short DistanceSqr(in short2 a, in short2 b)
		{
			return (short)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in short2 a, in short2 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static short2 Lerp(in short2 from, in short2 to, float lerp)
			{
				return new short2( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp));
			}

            public static short2 LerpUnclamped(in short2 from, in short2 to, float lerp)
			{
				return new short2( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp));
			}
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct int2 : IVector<int>, IEquatable<int2>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 2;
    public static readonly Type BASE_TYPE = typeof(int);
	public const string BASE_TYPENAME = "System.Int32";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const int COMPONENT_RATIO = 1 / (int)2;

	public static int2 Zero => new int2(0,0);
	public static int2 One => new int2(1,1);

		public static int2 MinValue => new int2(int.MinValue,int.MinValue);
		public static int2 MaxValue => new int2(int.MaxValue,int.MaxValue);

    
    
	

			        public readonly int x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int X => x;

	    		        public readonly int y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int Y => y;

	                 

	public readonly int this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				
				default: return default;
			}
		}
	}

    public readonly int GetElement(int index) => this[index];

    public readonly int GetElement(Axis2D axis) => this[(int)axis];

	public int2 SetComponent(int value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new int2(value,y);				
				case 1:
					return new int2(x,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public int2 SetX(int value) => SetComponent(value, 0);

                public int2 SetY(int value) => SetComponent(value, 1);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (int)MathX.AvgComponent(this);
            return new int2(c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new int2(c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(int);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public int2(int x = default(int), int y = default(int))
	{
    
				        this.x = x;
		    		        this.y = y;
		    	}

	public int2(int2 xy)
	{
        this = xy;
	}

	
	
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float2 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float2.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float2)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float2 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float2.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float2)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "int2"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral()})";
    }

    
	public static int2 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new int2( int.Parse(nums[0]), int.Parse(nums[1]));
	}

    
	public static int2 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new int2( int.Parse(nums[0], provider), int.Parse(nums[1], provider));
	}

	public static int2 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new int2( int.Parse(nums[0], style), int.Parse(nums[1], style));
	}

	public static int2 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new int2( int.Parse(nums[0], style, provider), int.Parse(nums[1], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out int2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = int.TryParse(nums[0], out int x);
		var parsed_y = int.TryParse(nums[1], out int y);

        if(parsed_x && parsed_y)
        {
            val = new int2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out int2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = int.TryParse(nums[0], numberStyles, formatProvider, out int x);
		var parsed_y = int.TryParse(nums[1], numberStyles, formatProvider, out int y);

        if(parsed_x && parsed_y)
        {
            val = new int2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    

