	public override bool Equals(object other)
	{
		if(other is int2)
			return Equals((int2)other);
		return false;
	}

	public bool Equals(int2 other)
	{
		return x==other.x&&y==other.y;
	}

	public override int GetHashCode()
	{
		unchecked
		{
			var hash = x.GetHashCode();
					hash = (hash*397) ^ y.GetHashCode();
					
			return hash;
		}
	}

