public static class Int2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in int2 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
				}

	public static int2 Read2D_Int32(this BinaryReader br)
	{
        		return new int2( br.ReadInt32(),  br.ReadInt32() ); 	}
}


