[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct long2 : IVector<long>, IEquatable<long2>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 2;
    public static readonly Type BASE_TYPE = typeof(long);
	public const string BASE_TYPENAME = "System.Int64";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const long COMPONENT_RATIO = 1 / (long)2;

	public static long2 Zero => new long2(0,0);
	public static long2 One => new long2(1,1);

		public static long2 MinValue => new long2(long.MinValue,long.MinValue);
		public static long2 MaxValue => new long2(long.MaxValue,long.MaxValue);

    
    
	

			        public readonly long x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly long X => x;

	    		        public readonly long y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly long Y => y;

	                 

	public readonly long this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				
				default: return default;
			}
		}
	}

    public readonly long GetElement(int index) => this[index];

    public readonly long GetElement(Axis2D axis) => this[(int)axis];

	public long2 SetComponent(long value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new long2(value,y);				
				case 1:
					return new long2(x,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public long2 SetX(long value) => SetComponent(value, 0);

                public long2 SetY(long value) => SetComponent(value, 1);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (long)MathX.AvgComponent(this);
            return new long2(c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new long2(c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(long);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public long2(long x = default(long), long y = default(long))
	{
    
				        this.x = x;
		    		        this.y = y;
		    	}

	public long2(long2 xy)
	{
        this = xy;
	}

	
	
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float2 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float2.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float2)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float2 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float2.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float2)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "long2"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral()})";
    }

    
	public static long2 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new long2( long.Parse(nums[0]), long.Parse(nums[1]));
	}

    
	public static long2 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new long2( long.Parse(nums[0], provider), long.Parse(nums[1], provider));
	}

	public static long2 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new long2( long.Parse(nums[0], style), long.Parse(nums[1], style));
	}

	public static long2 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new long2( long.Parse(nums[0], style, provider), long.Parse(nums[1], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out long2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = long.TryParse(nums[0], out long x);
		var parsed_y = long.TryParse(nums[1], out long y);

        if(parsed_x && parsed_y)
        {
            val = new long2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out long2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = long.TryParse(nums[0], numberStyles, formatProvider, out long x);
		var parsed_y = long.TryParse(nums[1], numberStyles, formatProvider, out long y);

        if(parsed_x && parsed_y)
        {
            val = new long2(x, y);
