public static class Long2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in long2 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
				}

	public static long2 Read2D_Int64(this BinaryReader br)
	{
        		return new long2( br.ReadInt64(),  br.ReadInt64() ); 	}
}


