[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct float2 : IVector<float>, IEquatable<float2>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 2;
    public static readonly Type BASE_TYPE = typeof(float);
	public const string BASE_TYPENAME = "System.Single";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const float COMPONENT_RATIO = 1 / (float)2;

	public static float2 Zero => new float2(0,0);
	public static float2 One => new float2(1,1);

		public static float2 MinValue => new float2(float.MinValue,float.MinValue);
		public static float2 MaxValue => new float2(float.MaxValue,float.MaxValue);

    
            public static readonly float2 UnitDiagonal = One.Normalized;

        public static float2 NaN => new float2(float.NaN,float.NaN);

        public static float2 PositiveInfinity => new float2(float.PositiveInfinity,float.PositiveInfinity);
		public static float2 NegativeInfinity => new float2(float.NegativeInfinity,float.NegativeInfinity);
        
	

			        public readonly float x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly float X => x;

	    		        public readonly float y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly float Y => y;

	                 

	public readonly float this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				
				default: return default;
			}
		}
	}

    public readonly float GetElement(int index) => this[index];

    public readonly float GetElement(Axis2D axis) => this[(int)axis];

	public float2 SetComponent(float value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new float2(value,y);				
				case 1:
					return new float2(x,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public float2 SetX(float value) => SetComponent(value, 0);

                public float2 SetY(float value) => SetComponent(value, 1);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (float)MathX.AvgComponent(this);
            return new float2(c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new float2(c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(float);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public float2(float x = default(float), float y = default(float))
	{
    
				        this.x = x;
		    		        this.y = y;
		    	}

	public float2(float2 xy)
	{
        this = xy;
	}

	
	
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float2 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float2.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float2)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float2 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float2.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float2)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
		[JsonIgnore]
		public readonly bool IsNaN
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => float.IsNaN(x)||float.IsNaN(y);
		}

		[JsonIgnore]
		public readonly bool IsInfinity
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => float.IsInfinity(x)||float.IsInfinity(y);
		}

		public readonly bool IsUniform(float tolerance = 0.00001f)
		{
			var delta = MathX.Min(x,y)*tolerance;
			
			return 
			(MathX.Abs(x - y) <= delta);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly bool Approximately(in float2 v, float tolerance)
		{
			return MathX.Abs(x-v.x) < tolerance&&MathX.Abs(y-v.y) < tolerance;
		}	

		
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "float2"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral()})";
    }

    
	public static float2 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new float2( float.Parse(nums[0]), float.Parse(nums[1]));
	}

    
	public static float2 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new float2( float.Parse(nums[0], provider), float.Parse(nums[1], provider));
	}

	public static float2 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new float2( float.Parse(nums[0], style), float.Parse(nums[1], style));
	}

	public static float2 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new float2( float.Parse(nums[0], style, provider), float.Parse(nums[1], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out float2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = float.TryParse(nums[0], out float x);
		var parsed_y = float.TryParse(nums[1], out float y);

        if(parsed_x && parsed_y)
        {
            val = new float2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out float2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = float.TryParse(nums[0], numberStyles, formatProvider, out float x);
		var parsed_y = float.TryParse(nums[1], numberStyles, formatProvider, out float y);

        if(parsed_x && parsed_y)
        {
            val = new float2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    

