	{
		return a.x==b.x&&a.y==b.y;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool operator !=(in float2 a, in float2 b)
	{
		return a.x!=b.x||a.y!=b.y;
	}

