public static class Float2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in float2 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
				}

	public static float2 Read2D_Single(this BinaryReader br)
	{
        		return new float2( br.ReadSingle(),  br.ReadSingle() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static float2 Select(this bool2 mask, in float2 onTrue, in float2 onFalse) => new float2(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float MinComponent(in float2 v)
	{
		return Min(v.x,v.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float MaxComponent(in float2 v)
	{
		return Max(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in float2 v)
	{
		return MaxIndex(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float2 Min(params float2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static float2 Max(params float2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in float2 a, in float2 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in float2 a, in float2 b, float epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float DistanceSqr(in float2 a, in float2 b)
		{
			return (float)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in float2 a, in float2 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
		
