			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float Dot(in float2 a, in float2 b)
			{
				return a.x*b.x + a.y*b.y;
			}
			 
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float2 Project(in float2 a, in float2 b)
			{
				var bNorm = b.Normalized;
				return bNorm * Dot(a,bNorm);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static float2 Reject(in float2 a, in float2 b) => a - Project(a,b);

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float AngleRad(in float2 a, in float2 b)
			{
				return MathX.Acos(MathX.Clamp(MathX.Dot(a.Normalized,b.Normalized), -1, 1));
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float Angle(in float2 a, in float2 b) => AngleRad(a, b) * MathX.Rad2Deg;


            
                // Computes the angle between the two vectors, with the sign indicating if it goes clockwise or counter-clockwise.
                // Positive is clockwise and negative counter-clockwise. Positive Y is up.
                [MethodImpl(MethodImplOptions.AggressiveInlining)]
			    public static float DeltaAngle(in float2 from, in float2 to) => DeltaAngleRad(from, to) * MathX.Rad2Deg;

                public static float DeltaAngleRad(in float2 from, in float2 to)
                {
                    var dot = from.x * to.x + from.y * to.y;
                    var det = from.x * to.y - from.y * to.x;

                    return -Atan2(det, dot);
                }

                
			public static float2 AxisAligned(in float2 v)
			{
				var abs = MathX.Abs(v);

									if(abs.x > abs.y)
						return new float2(MathX.Sign(v.x), 0);
					else
						return new float2(0, MathX.Sign(v.y));
								}

			
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static bool IsBetween(this float2 value, in float2 from, in float2 to)
			{
				return value.x.IsBetween(from.x, to.x)&&value.y.IsBetween(from.y, to.y);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float2 Lerp(in float2 from, in float2 to, float t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float2 Lerp(in float2 from, float to, float t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return new float2(to, to);

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float2 Lerp(float from, in float2 to, float t)
			{
				if(t <= 0)
					return new float2(from, from);
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			public static float2 Slerp(float2 from, in float2 to, float lerp)
			{
				var dot = Dot(from, to);

                // Break singularity when the vectors are nearly opposite of each other
                if(dot < -0.999999f)
                    from = (from + 1e-3f).Normalized;

				dot = Clamp(dot, -1, 1);

				var theta = Acos(dot)*lerp;
				var relativeVec = to - from*dot;
				relativeVec = relativeVec.Normalized;

				return ((from*Cos(theta)) + (relativeVec*Sin(theta)));
			}

            // This slerps the direction uniformly, while also lerping the magnitude
            public static float2 SlerpWithMagnitude(in float2 from, in float2 to, float lerp)
            {
                var fromDir = from.GetNormalized(out var fromMag);
                var toDir = to.GetNormalized(out var toMag);

                var newMag = MathX.LerpUnclamped(fromMag, toMag, lerp);

                // If one of the vectors is zero, just take the direction from the other vector
                // rather than slerping it
                if(MathX.Approximately(fromMag, 0))
                    return toDir * newMag;

                if(MathX.Approximately(toMag, 0))
                    return fromDir * newMag;

                return Slerp(fromDir, toDir, lerp) * newMag;
            }

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float2 ClampMagnitude(in float2 v, float maxMagnitude, float minMagnitude = 0)
			{
				var mag = v.Magnitude;

				if(mag > maxMagnitude)
					return v * (maxMagnitude / mag);

				if(mag < minMagnitude && mag > 0)
					return v * (minMagnitude / mag);

				return v;
			}

		
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
