		public readonly bool Approximately(in double2 v, double tolerance)
		{
			return MathX.Abs(x-v.x) < tolerance&&MathX.Abs(y-v.y) < tolerance;
		}	

		
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "double2"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral()})";
    }

    
	public static double2 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new double2( double.Parse(nums[0]), double.Parse(nums[1]));
	}

    
	public static double2 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new double2( double.Parse(nums[0], provider), double.Parse(nums[1], provider));
	}

	public static double2 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new double2( double.Parse(nums[0], style), double.Parse(nums[1], style));
	}

	public static double2 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 2);

		return new double2( double.Parse(nums[0], style, provider), double.Parse(nums[1], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out double2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = double.TryParse(nums[0], out double x);
		var parsed_y = double.TryParse(nums[1], out double y);

        if(parsed_x && parsed_y)
        {
            val = new double2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out double2 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 2);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = double.TryParse(nums[0], numberStyles, formatProvider, out double x);
		var parsed_y = double.TryParse(nums[1], numberStyles, formatProvider, out double y);

        if(parsed_x && parsed_y)
        {
            val = new double2(x, y);
            return true;
        }

        val = default;
        return false;
	}

    

