public static class Double2Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in double2 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
				}

	public static double2 Read2D_Double(this BinaryReader br)
	{
        		return new double2( br.ReadDouble(),  br.ReadDouble() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static double2 Select(this bool2 mask, in double2 onTrue, in double2 onFalse) => new double2(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static double MinComponent(in double2 v)
	{
		return Min(v.x,v.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static double MaxComponent(in double2 v)
	{
		return Max(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in double2 v)
	{
		return MaxIndex(v.x,v.y);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static double2 Min(params double2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static double2 Max(params double2[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in double2 a, in double2 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in double2 a, in double2 b, double epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double DistanceSqr(in double2 a, in double2 b)
		{
			return (double)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double Distance(in double2 a, in double2 b)
		{
			return MathX.Sqrt((double)DistanceSqr(a, b));
		}

#endregion

    
		
