			[MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static double2 Reject(in double2 a, in double2 b) => a - Project(a,b);

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double AngleRad(in double2 a, in double2 b)
			{
				return MathX.Acos(MathX.Clamp(MathX.Dot(a.Normalized,b.Normalized), -1, 1));
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double Angle(in double2 a, in double2 b) => AngleRad(a, b) * MathX.Rad2Deg;


            
                // Computes the angle between the two vectors, with the sign indicating if it goes clockwise or counter-clockwise.
                // Positive is clockwise and negative counter-clockwise. Positive Y is up.
                [MethodImpl(MethodImplOptions.AggressiveInlining)]
			    public static double DeltaAngle(in double2 from, in double2 to) => DeltaAngleRad(from, to) * MathX.Rad2Deg;

                public static double DeltaAngleRad(in double2 from, in double2 to)
                {
                    var dot = from.x * to.x + from.y * to.y;
                    var det = from.x * to.y - from.y * to.x;

                    return -Atan2(det, dot);
                }

                
			public static double2 AxisAligned(in double2 v)
			{
				var abs = MathX.Abs(v);

									if(abs.x > abs.y)
						return new double2(MathX.Sign(v.x), 0);
					else
						return new double2(0, MathX.Sign(v.y));
								}

			
