			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double2 Lerp(in double2 from, in double2 to, double t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double2 Lerp(in double2 from, double to, double t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return new double2(to, to);

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double2 Lerp(double from, in double2 to, double t)
			{
				if(t <= 0)
					return new double2(from, from);
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			public static double2 Slerp(double2 from, in double2 to, float lerp)
			{
				var dot = Dot(from, to);

                // Break singularity when the vectors are nearly opposite of each other
                if(dot < -0.999999)
                    from = (from + 1e-3f).Normalized;

				dot = Clamp(dot, -1, 1);

				var theta = Acos(dot)*lerp;
				var relativeVec = to - from*dot;
				relativeVec = relativeVec.Normalized;

				return ((from*Cos(theta)) + (relativeVec*Sin(theta)));
			}

            // This slerps the direction uniformly, while also lerping the magnitude
            public static double2 SlerpWithMagnitude(in double2 from, in double2 to, float lerp)
            {
                var fromDir = from.GetNormalized(out var fromMag);
                var toDir = to.GetNormalized(out var toMag);

                var newMag = MathX.LerpUnclamped(fromMag, toMag, lerp);

                // If one of the vectors is zero, just take the direction from the other vector
                // rather than slerping it
                if(MathX.Approximately(fromMag, 0))
                    return toDir * newMag;

                if(MathX.Approximately(toMag, 0))
                    return fromDir * newMag;

                return Slerp(fromDir, toDir, lerp) * newMag;
            }

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double2 ClampMagnitude(in double2 v, double maxMagnitude, double minMagnitude = 0)
			{
				var mag = v.Magnitude;

				if(mag > maxMagnitude)
					return v * (maxMagnitude / mag);

				if(mag < minMagnitude && mag > 0)
					return v * (minMagnitude / mag);

				return v;
			}

					public static double2 Lerp(in double2 from, in double2 to, float t)
			{
				return Lerp(from, to, (double)t);
			}
			
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct bool3 : IVector<bool>, IEquatable<bool3>, IFormattable 
{
	public const int DIMENSIONS = 3;
    public static readonly Type BASE_TYPE = typeof(bool);
	public const string BASE_TYPENAME = "System.Boolean";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

            public static bool3 False => new bool3(false,false,false);
	    public static bool3 True => new bool3(true,true,true);

		
    
    
	

	public readonly byte flags;
        public readonly bool x => (flags & (1<<0)) != 0;
            public readonly bool y => (flags & (1<<1)) != 0;
            public readonly bool z => (flags & (1<<2)) != 0;
                         

	public readonly bool this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly bool GetElement(int index) => this[index];

    public readonly bool GetElement(Axis3D axis) => this[(int)axis];

	public bool3 SetComponent(bool value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new bool3(value,y,z);				
				case 1:
					return new bool3(x,value,z);				
				case 2:
					return new bool3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public bool3 SetX(bool value) => SetComponent(value, 0);

                public bool3 SetY(bool value) => SetComponent(value, 1);

                public bool3 SetZ(bool value) => SetComponent(value, 2);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    int trueCount = 0;
            int falseCount = 0;

            for(int i = 0; i < 3; i++)
            {
                if(this[i])
                    trueCount++;
                else
                    falseCount++;
            }

            if(trueCount >= falseCount)
                return new bool3(true,true,true);
            else
                return new bool3(false,false,false);
                }

