	public static bool3 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new bool3( bool.Parse(nums[0]), bool.Parse(nums[1]), bool.Parse(nums[2]));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out bool3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = bool.TryParse(nums[0], out bool x);
		var parsed_y = bool.TryParse(nums[1], out bool y);
		var parsed_z = bool.TryParse(nums[2], out bool z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new bool3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    

