		public readonly bool All() => flags == 7;//x && y && z;
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly bool None() => flags == 0; // !Any();

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly bool XOR() => x ^ y ^ z; //x ^ y ^ z;


		
