public static class Bool3Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in bool3 v)
	{
		bw.Write(v.flags);	}

	public static bool3 Read3D_Boolean(this BinaryReader br)
	{
        return new bool3(br.ReadByte());	}
