	public readonly byte this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly byte GetElement(int index) => this[index];

    public readonly byte GetElement(Axis3D axis) => this[(int)axis];

	public byte3 SetComponent(byte value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new byte3(value,y,z);				
				case 1:
					return new byte3(x,value,z);				
				case 2:
					return new byte3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public byte3 SetX(byte value) => SetComponent(value, 0);

                public byte3 SetY(byte value) => SetComponent(value, 1);

                public byte3 SetZ(byte value) => SetComponent(value, 2);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (byte)MathX.AvgComponent(this);
            return new byte3(c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new byte3(c,c,c);
    }

