public static class Ushort3Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in ushort3 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
				}

	public static ushort3 Read3D_UInt16(this BinaryReader br)
	{
        		return new ushort3( br.ReadUInt16(),  br.ReadUInt16(),  br.ReadUInt16() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ushort3 Select(this bool3 mask, in ushort3 onTrue, in ushort3 onFalse) => new ushort3(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort MinComponent(in ushort3 v)
	{
		return Min(v.x,v.y,v.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort MaxComponent(in ushort3 v)
	{
		return Max(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in ushort3 v)
	{
		return MaxIndex(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort3 Min(params ushort3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort3 Max(params ushort3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in ushort3 a, in ushort3 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in ushort3 a, in ushort3 b, ushort epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static ushort DistanceSqr(in ushort3 a, in ushort3 b)
		{
			return (ushort)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in ushort3 a, in ushort3 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static ushort3 Lerp(in ushort3 from, in ushort3 to, float lerp)
			{
				return new ushort3( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp),Lerp(from.z, to.z, lerp));
			}

            public static ushort3 LerpUnclamped(in ushort3 from, in ushort3 to, float lerp)
			{
				return new ushort3( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp),LerpUnclamped(from.z, to.z, lerp));
			}
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct uint3 : IVector<uint>, IEquatable<uint3>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 3;
    public static readonly Type BASE_TYPE = typeof(uint);
	public const string BASE_TYPENAME = "System.UInt32";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const uint COMPONENT_RATIO = 1 / (uint)3;

	public static uint3 Zero => new uint3(0,0,0);
	public static uint3 One => new uint3(1,1,1);

		public static uint3 MinValue => new uint3(uint.MinValue,uint.MinValue,uint.MinValue);
		public static uint3 MaxValue => new uint3(uint.MaxValue,uint.MaxValue,uint.MaxValue);

    
    
	

			        public readonly uint x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly uint X => x;

	    		        public readonly uint y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly uint Y => y;

	    		        public readonly uint z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly uint Z => z;

	                 

	public readonly uint this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly uint GetElement(int index) => this[index];

    public readonly uint GetElement(Axis3D axis) => this[(int)axis];

	public uint3 SetComponent(uint value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new uint3(value,y,z);				
				case 1:
					return new uint3(x,value,z);				
				case 2:
					return new uint3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public uint3 SetX(uint value) => SetComponent(value, 0);

                public uint3 SetY(uint value) => SetComponent(value, 1);

                public uint3 SetZ(uint value) => SetComponent(value, 2);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (uint)MathX.AvgComponent(this);
            return new uint3(c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new uint3(c,c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(uint);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public uint3(uint x = default(uint), uint y = default(uint), uint z = default(uint))
	{
    
				        this.x = x;
		    		        this.y = y;
		    		        this.z = z;
		    	}

	public uint3(uint3 xyz)
	{
        this = xyz;
	}

	
		public uint3(in uint2 xy, uint z) : this(xy.x, xy.y, z)
		{
		}

