		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float3 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float3.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float3)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float3 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float3.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float3)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y+(float)z*(float)z;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider)+ $"{separator} " + z.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat)+ $"{separator} " + z.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider)+ $"{separator} " + z.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "uint3"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral() + ", " + z.ToCodeLiteral()})";
    }

    
	public static uint3 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new uint3( uint.Parse(nums[0]), uint.Parse(nums[1]), uint.Parse(nums[2]));
	}

    
	public static uint3 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new uint3( uint.Parse(nums[0], provider), uint.Parse(nums[1], provider), uint.Parse(nums[2], provider));
	}

	public static uint3 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new uint3( uint.Parse(nums[0], style), uint.Parse(nums[1], style), uint.Parse(nums[2], style));
	}

	public static uint3 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new uint3( uint.Parse(nums[0], style, provider), uint.Parse(nums[1], style, provider), uint.Parse(nums[2], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out uint3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = uint.TryParse(nums[0], out uint x);
		var parsed_y = uint.TryParse(nums[1], out uint y);
		var parsed_z = uint.TryParse(nums[2], out uint z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new uint3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out uint3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = uint.TryParse(nums[0], numberStyles, formatProvider, out uint x);
		var parsed_y = uint.TryParse(nums[1], numberStyles, formatProvider, out uint y);
		var parsed_z = uint.TryParse(nums[2], numberStyles, formatProvider, out uint z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new uint3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    

