public static class Uint3Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in uint3 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
				}

	public static uint3 Read3D_UInt32(this BinaryReader br)
	{
        		return new uint3( br.ReadUInt32(),  br.ReadUInt32(),  br.ReadUInt32() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static uint3 Select(this bool3 mask, in uint3 onTrue, in uint3 onFalse) => new uint3(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint MinComponent(in uint3 v)
	{
		return Min(v.x,v.y,v.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint MaxComponent(in uint3 v)
	{
		return Max(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in uint3 v)
	{
		return MaxIndex(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint3 Min(params uint3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint3 Max(params uint3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in uint3 a, in uint3 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in uint3 a, in uint3 b, uint epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon);
	}

