		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static uint DistanceSqr(in uint3 a, in uint3 b)
		{
			return (uint)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in uint3 a, in uint3 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
		
