[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct ulong3 : IVector<ulong>, IEquatable<ulong3>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 3;
    public static readonly Type BASE_TYPE = typeof(ulong);
	public const string BASE_TYPENAME = "System.UInt64";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const ulong COMPONENT_RATIO = 1 / (ulong)3;

	public static ulong3 Zero => new ulong3(0,0,0);
	public static ulong3 One => new ulong3(1,1,1);

		public static ulong3 MinValue => new ulong3(ulong.MinValue,ulong.MinValue,ulong.MinValue);
		public static ulong3 MaxValue => new ulong3(ulong.MaxValue,ulong.MaxValue,ulong.MaxValue);

    
    
	

			        public readonly ulong x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong X => x;

	    		        public readonly ulong y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong Y => y;

	    		        public readonly ulong z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong Z => z;

	                 

	public readonly ulong this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly ulong GetElement(int index) => this[index];

    public readonly ulong GetElement(Axis3D axis) => this[(int)axis];

	public ulong3 SetComponent(ulong value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new ulong3(value,y,z);				
				case 1:
					return new ulong3(x,value,z);				
				case 2:
					return new ulong3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public ulong3 SetX(ulong value) => SetComponent(value, 0);

                public ulong3 SetY(ulong value) => SetComponent(value, 1);

                public ulong3 SetZ(ulong value) => SetComponent(value, 2);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (ulong)MathX.AvgComponent(this);
            return new ulong3(c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new ulong3(c,c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(ulong);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public ulong3(ulong x = default(ulong), ulong y = default(ulong), ulong z = default(ulong))
	{
    
				        this.x = x;
		    		        this.y = y;
		    		        this.z = z;
		    	}

	public ulong3(ulong3 xyz)
	{
        this = xyz;
	}

	
		public ulong3(in ulong2 xy, ulong z) : this(xy.x, xy.y, z)
		{
		}

		public ulong3(ulong x, in ulong2 yz) : this(x, yz.x, yz.y)
		{
		}

		
	
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float3 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float3.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float3)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float3 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float3.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float3)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y+(float)z*(float)z;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider)+ $"{separator} " + z.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
