	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider)+ $"{separator} " + z.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "ulong3"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral() + ", " + z.ToCodeLiteral()})";
    }

    
	public static ulong3 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new ulong3( ulong.Parse(nums[0]), ulong.Parse(nums[1]), ulong.Parse(nums[2]));
	}

    
	public static ulong3 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new ulong3( ulong.Parse(nums[0], provider), ulong.Parse(nums[1], provider), ulong.Parse(nums[2], provider));
	}

	public static ulong3 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new ulong3( ulong.Parse(nums[0], style), ulong.Parse(nums[1], style), ulong.Parse(nums[2], style));
	}

	public static ulong3 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new ulong3( ulong.Parse(nums[0], style, provider), ulong.Parse(nums[1], style, provider), ulong.Parse(nums[2], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out ulong3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ulong.TryParse(nums[0], out ulong x);
		var parsed_y = ulong.TryParse(nums[1], out ulong y);
		var parsed_z = ulong.TryParse(nums[2], out ulong z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new ulong3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out ulong3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ulong.TryParse(nums[0], numberStyles, formatProvider, out ulong x);
		var parsed_y = ulong.TryParse(nums[1], numberStyles, formatProvider, out ulong y);
		var parsed_z = ulong.TryParse(nums[2], numberStyles, formatProvider, out ulong z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new ulong3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    

