public static class Ulong3Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in ulong3 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
				}

	public static ulong3 Read3D_UInt64(this BinaryReader br)
	{
        		return new ulong3( br.ReadUInt64(),  br.ReadUInt64(),  br.ReadUInt64() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ulong3 Select(this bool3 mask, in ulong3 onTrue, in ulong3 onFalse) => new ulong3(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ulong MinComponent(in ulong3 v)
	{
		return Min(v.x,v.y,v.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ulong MaxComponent(in ulong3 v)
	{
		return Max(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in ulong3 v)
	{
		return MaxIndex(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ulong3 Min(params ulong3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ulong3 Max(params ulong3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in ulong3 a, in ulong3 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in ulong3 a, in ulong3 b, ulong epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static ulong DistanceSqr(in ulong3 a, in ulong3 b)
		{
			return (ulong)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in ulong3 a, in ulong3 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
		
