	public readonly sbyte this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly sbyte GetElement(int index) => this[index];

    public readonly sbyte GetElement(Axis3D axis) => this[(int)axis];

	public sbyte3 SetComponent(sbyte value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new sbyte3(value,y,z);				
				case 1:
					return new sbyte3(x,value,z);				
				case 2:
					return new sbyte3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public sbyte3 SetX(sbyte value) => SetComponent(value, 0);

                public sbyte3 SetY(sbyte value) => SetComponent(value, 1);

                public sbyte3 SetZ(sbyte value) => SetComponent(value, 2);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (sbyte)MathX.AvgComponent(this);
            return new sbyte3(c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new sbyte3(c,c,c);
    }

