	public static sbyte3 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new sbyte3( sbyte.Parse(nums[0]), sbyte.Parse(nums[1]), sbyte.Parse(nums[2]));
	}

    
	public static sbyte3 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new sbyte3( sbyte.Parse(nums[0], provider), sbyte.Parse(nums[1], provider), sbyte.Parse(nums[2], provider));
	}

	public static sbyte3 Parse(string s, NumberStyles style)
	{
