	}

    
	// TryParse variant

	public static bool TryParse(string s, out sbyte3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = sbyte.TryParse(nums[0], out sbyte x);
		var parsed_y = sbyte.TryParse(nums[1], out sbyte y);
		var parsed_z = sbyte.TryParse(nums[2], out sbyte z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new sbyte3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out sbyte3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = sbyte.TryParse(nums[0], numberStyles, formatProvider, out sbyte x);
		var parsed_y = sbyte.TryParse(nums[1], numberStyles, formatProvider, out sbyte y);
		var parsed_z = sbyte.TryParse(nums[2], numberStyles, formatProvider, out sbyte z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new sbyte3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    

