public static class Sbyte3Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in sbyte3 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
				}

	public static sbyte3 Read3D_SByte(this BinaryReader br)
	{
        		return new sbyte3( br.ReadSByte(),  br.ReadSByte(),  br.ReadSByte() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static sbyte3 Select(this bool3 mask, in sbyte3 onTrue, in sbyte3 onFalse) => new sbyte3(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static sbyte MinComponent(in sbyte3 v)
	{
		return Min(v.x,v.y,v.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static sbyte MaxComponent(in sbyte3 v)
	{
		return Max(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in sbyte3 v)
	{
		return MaxIndex(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static sbyte3 Min(params sbyte3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static sbyte3 Max(params sbyte3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in sbyte3 a, in sbyte3 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in sbyte3 a, in sbyte3 b, sbyte epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static sbyte DistanceSqr(in sbyte3 a, in sbyte3 b)
		{
			return (sbyte)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in sbyte3 a, in sbyte3 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static sbyte3 Lerp(in sbyte3 from, in sbyte3 to, float lerp)
			{
				return new sbyte3( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp),Lerp(from.z, to.z, lerp));
			}

            public static sbyte3 LerpUnclamped(in sbyte3 from, in sbyte3 to, float lerp)
			{
				return new sbyte3( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp),LerpUnclamped(from.z, to.z, lerp));
			}
		}


