	public static short3 One => new short3(1,1,1);

		public static short3 MinValue => new short3(short.MinValue,short.MinValue,short.MinValue);
		public static short3 MaxValue => new short3(short.MaxValue,short.MaxValue,short.MaxValue);

    
    
	

			        public readonly short x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
