	public readonly short this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly short GetElement(int index) => this[index];

    public readonly short GetElement(Axis3D axis) => this[(int)axis];

	public short3 SetComponent(short value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new short3(value,y,z);				
				case 1:
					return new short3(x,value,z);				
				case 2:
					return new short3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public short3 SetX(short value) => SetComponent(value, 0);

                public short3 SetY(short value) => SetComponent(value, 1);

                public short3 SetZ(short value) => SetComponent(value, 2);

        
