public static class Short3Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in short3 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
				}

	public static short3 Read3D_Int16(this BinaryReader br)
	{
        		return new short3( br.ReadInt16(),  br.ReadInt16(),  br.ReadInt16() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static short3 Select(this bool3 mask, in short3 onTrue, in short3 onFalse) => new short3(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short MinComponent(in short3 v)
	{
		return Min(v.x,v.y,v.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short MaxComponent(in short3 v)
	{
		return Max(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in short3 v)
	{
		return MaxIndex(v.x,v.y,v.z);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short3 Min(params short3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short3 Max(params short3[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in short3 a, in short3 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in short3 a, in short3 b, short epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static short DistanceSqr(in short3 a, in short3 b)
		{
			return (short)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in short3 a, in short3 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static short3 Lerp(in short3 from, in short3 to, float lerp)
			{
				return new short3( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp),Lerp(from.z, to.z, lerp));
			}

            public static short3 LerpUnclamped(in short3 from, in short3 to, float lerp)
			{
				return new short3( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp),LerpUnclamped(from.z, to.z, lerp));
			}
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct int3 : IVector<int>, IEquatable<int3>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 3;
    public static readonly Type BASE_TYPE = typeof(int);
	public const string BASE_TYPENAME = "System.Int32";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const int COMPONENT_RATIO = 1 / (int)3;

	public static int3 Zero => new int3(0,0,0);
	public static int3 One => new int3(1,1,1);

		public static int3 MinValue => new int3(int.MinValue,int.MinValue,int.MinValue);
		public static int3 MaxValue => new int3(int.MaxValue,int.MaxValue,int.MaxValue);

    
    
	

			        public readonly int x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int X => x;

	    		        public readonly int y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int Y => y;

	    		        public readonly int z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int Z => z;

	                 

	public readonly int this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly int GetElement(int index) => this[index];

    public readonly int GetElement(Axis3D axis) => this[(int)axis];

	public int3 SetComponent(int value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new int3(value,y,z);				
				case 1:
					return new int3(x,value,z);				
				case 2:
					return new int3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public int3 SetX(int value) => SetComponent(value, 0);

                public int3 SetY(int value) => SetComponent(value, 1);

                public int3 SetZ(int value) => SetComponent(value, 2);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (int)MathX.AvgComponent(this);
            return new int3(c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new int3(c,c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(int);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public int3(int x = default(int), int y = default(int), int z = default(int))
	{
    
				        this.x = x;
		    		        this.y = y;
		    		        this.z = z;
		    	}

	public int3(int3 xyz)
	{
        this = xyz;
	}

	
		public int3(in int2 xy, int z) : this(xy.x, xy.y, z)
		{
		}

		public int3(int x, in int2 yz) : this(x, yz.x, yz.y)
		{
		}

		
	
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float3 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float3.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float3)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float3 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float3.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float3)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y+(float)z*(float)z;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider)+ $"{separator} " + z.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat)+ $"{separator} " + z.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider)+ $"{separator} " + z.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "int3"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral() + ", " + z.ToCodeLiteral()})";
    }

    
	public static int3 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new int3( int.Parse(nums[0]), int.Parse(nums[1]), int.Parse(nums[2]));
	}

    
	public static int3 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new int3( int.Parse(nums[0], provider), int.Parse(nums[1], provider), int.Parse(nums[2], provider));
	}

	public static int3 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new int3( int.Parse(nums[0], style), int.Parse(nums[1], style), int.Parse(nums[2], style));
	}

	public static int3 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new int3( int.Parse(nums[0], style, provider), int.Parse(nums[1], style, provider), int.Parse(nums[2], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out int3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = int.TryParse(nums[0], out int x);
		var parsed_y = int.TryParse(nums[1], out int y);
		var parsed_z = int.TryParse(nums[2], out int z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new int3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out int3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = int.TryParse(nums[0], numberStyles, formatProvider, out int x);
		var parsed_y = int.TryParse(nums[1], numberStyles, formatProvider, out int y);
		var parsed_z = int.TryParse(nums[2], numberStyles, formatProvider, out int z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new int3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    

