        public readonly int3 Mask(bool3 mask, int masked = default(int)) => new int3(mask.x ? x : masked, mask.y ? y : masked, mask.z ? z : masked);

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly int3 Mask(bool3 mask, in int3 masked) => new int3(mask.x ? x : masked.x, mask.y ? y : masked.y, mask.z ? z : masked.z);

        
