public static class Int3Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in int3 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
				}

	public static int3 Read3D_Int32(this BinaryReader br)
	{
        		return new int3( br.ReadInt32(),  br.ReadInt32(),  br.ReadInt32() ); 	}
}


