[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct long3 : IVector<long>, IEquatable<long3>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 3;
    public static readonly Type BASE_TYPE = typeof(long);
	public const string BASE_TYPENAME = "System.Int64";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const long COMPONENT_RATIO = 1 / (long)3;

	public static long3 Zero => new long3(0,0,0);
	public static long3 One => new long3(1,1,1);

		public static long3 MinValue => new long3(long.MinValue,long.MinValue,long.MinValue);
		public static long3 MaxValue => new long3(long.MaxValue,long.MaxValue,long.MaxValue);

    
    
	

			        public readonly long x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly long X => x;

	    		        public readonly long y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly long Y => y;

	    		        public readonly long z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly long Z => z;

	                 

	public readonly long this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly long GetElement(int index) => this[index];

    public readonly long GetElement(Axis3D axis) => this[(int)axis];

	public long3 SetComponent(long value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new long3(value,y,z);				
				case 1:
					return new long3(x,value,z);				
				case 2:
					return new long3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public long3 SetX(long value) => SetComponent(value, 0);

                public long3 SetY(long value) => SetComponent(value, 1);

                public long3 SetZ(long value) => SetComponent(value, 2);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (long)MathX.AvgComponent(this);
            return new long3(c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new long3(c,c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(long);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public long3(long x = default(long), long y = default(long), long z = default(long))
	{
    
				        this.x = x;
		    		        this.y = y;
		    		        this.z = z;
		    	}

	public long3(long3 xyz)
	{
        this = xyz;
	}

	
		public long3(in long2 xy, long z) : this(xy.x, xy.y, z)
		{
		}

		public long3(long x, in long2 yz) : this(x, yz.x, yz.y)
		{
		}

		
	
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float3 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float3.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float3)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float3 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float3.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float3)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y+(float)z*(float)z;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
