        {
            val = new long3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out long3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = long.TryParse(nums[0], numberStyles, formatProvider, out long x);
		var parsed_y = long.TryParse(nums[1], numberStyles, formatProvider, out long y);
		var parsed_z = long.TryParse(nums[2], numberStyles, formatProvider, out long z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new long3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    

