{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in long3 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
				}

	public static long3 Read3D_Int64(this BinaryReader br)
	{
        		return new long3( br.ReadInt64(),  br.ReadInt64(),  br.ReadInt64() ); 	}
}


