[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct float3 : IVector<float>, IEquatable<float3>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 3;
    public static readonly Type BASE_TYPE = typeof(float);
	public const string BASE_TYPENAME = "System.Single";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const float COMPONENT_RATIO = 1 / (float)3;

	public static float3 Zero => new float3(0,0,0);
	public static float3 One => new float3(1,1,1);

		public static float3 MinValue => new float3(float.MinValue,float.MinValue,float.MinValue);
		public static float3 MaxValue => new float3(float.MaxValue,float.MaxValue,float.MaxValue);

    
            public static readonly float3 UnitDiagonal = One.Normalized;

        public static float3 NaN => new float3(float.NaN,float.NaN,float.NaN);

        public static float3 PositiveInfinity => new float3(float.PositiveInfinity,float.PositiveInfinity,float.PositiveInfinity);
		public static float3 NegativeInfinity => new float3(float.NegativeInfinity,float.NegativeInfinity,float.NegativeInfinity);
        
	
		public static float3 Forward => new float3(0,0,1);
		public static float3 Backward => new float3(0,0,-1);

		public static float3 Up => new float3(0,1,0);
		public static float3 Down => new float3(0,-1,0);

		public static float3 Right => new float3(1,0,0);
		public static float3 Left => new float3(-1,0,0);

		

			        public readonly float x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly float X => x;

	    		        public readonly float y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly float Y => y;

	    		        public readonly float z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly float Z => z;

	                 

	public readonly float this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				
				default: return default;
			}
		}
	}

    public readonly float GetElement(int index) => this[index];

    public readonly float GetElement(Axis3D axis) => this[(int)axis];

	public float3 SetComponent(float value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new float3(value,y,z);				
				case 1:
					return new float3(x,value,z);				
				case 2:
					return new float3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public float3 SetX(float value) => SetComponent(value, 0);

                public float3 SetY(float value) => SetComponent(value, 1);

                public float3 SetZ(float value) => SetComponent(value, 2);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (float)MathX.AvgComponent(this);
            return new float3(c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new float3(c,c,c);
    }

