		}

		public readonly bool IsUniform(float tolerance = 0.00001f)
		{
			var delta = MathX.Min(x,y,z)*tolerance;
			
			return 
			(MathX.Abs(x - y) <= delta) && (MathX.Abs(y - z) <= delta);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly bool Approximately(in float3 v, float tolerance)
		{
			return MathX.Abs(x-v.x) < tolerance&&MathX.Abs(y-v.y) < tolerance&&MathX.Abs(z-v.z) < tolerance;
		}	

		
