	{
		var nums = PrimitivesUtility.ExtractElements(s, 3);

		return new float3( float.Parse(nums[0], style, provider), float.Parse(nums[1], style, provider), float.Parse(nums[2], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out float3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = float.TryParse(nums[0], out float x);
		var parsed_y = float.TryParse(nums[1], out float y);
		var parsed_z = float.TryParse(nums[2], out float z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new float3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out float3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = float.TryParse(nums[0], numberStyles, formatProvider, out float x);
		var parsed_y = float.TryParse(nums[1], numberStyles, formatProvider, out float y);
		var parsed_z = float.TryParse(nums[2], numberStyles, formatProvider, out float z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new float3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    

