		[MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly float3 Mask(bool3 mask, float masked = default(float)) => new float3(mask.x ? x : masked, mask.y ? y : masked, mask.z ? z : masked);

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly float3 Mask(bool3 mask, in float3 masked) => new float3(mask.x ? x : masked.x, mask.y ? y : masked.y, mask.z ? z : masked.z);

        
#endregion

