		public static bool3 operator <(float3 v, float n)
		{
			return new bool3(v.x<n, v.y<n, v.z<n);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static bool3 operator >(float3 a, float3 b)
		{
			return new bool3(a.x>b.x, a.y>b.y, a.z>b.z);
		}

