			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float AvgComponent(in float3 v)
			{
				return (v.x + v.y + v.z) * float3.COMPONENT_RATIO;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float Dot(in float3 a, in float3 b)
			{
				return a.x*b.x + a.y*b.y + a.z*b.z;
			}
			 
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float3 Project(in float3 a, in float3 b)
			{
				var bNorm = b.Normalized;
				return bNorm * Dot(a,bNorm);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static float3 Reject(in float3 a, in float3 b) => a - Project(a,b);

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float AngleRad(in float3 a, in float3 b)
			{
				return MathX.Acos(MathX.Clamp(MathX.Dot(a.Normalized,b.Normalized), -1, 1));
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float Angle(in float3 a, in float3 b) => AngleRad(a, b) * MathX.Rad2Deg;


            
			public static float3 AxisAligned(in float3 v)
			{
				var abs = MathX.Abs(v);

										if(abs.x > abs.y && abs.x > abs.z)
							return new float3(MathX.Sign(v.x), 0, 0);

						if(abs.y > abs.z)
							return new float3(0, MathX.Sign(v.y), 0);

						return new float3(0, 0, MathX.Sign(v.z));
								}

			
			static readonly floatQ float_orthoX = floatQ.AxisAngle(float3.Right, 90);
			static readonly floatQ float_orthoY = floatQ.AxisAngle(float3.Up, 90);

			// based on this: http://stackoverflow.com/questions/3684269/component-of-a-quaternion-rotation-around-an-axis
			public static void Orthonormals(in float3 normal, out float3 ortho0, out float3 ortho1)
			{
				var normNormal = normal.Normalized;

				var w = float_orthoX * normNormal;
				if(MathX.Dot(normal,w) > 0.6f)
					w = float_orthoY * normNormal;	
					
				ortho0 = MathX.Cross(normal, w);
				ortho1 = MathX.Cross(normal, ortho0);
			}

			public static void Orthonormalize(ref float3 normal, ref float3 tangent)
			{
				if(normal == float3.Zero)
					normal = float3.Right;
				else
					normal = normal.Normalized;

				var temp = MathX.Cross(normal, tangent);

				if(temp == float3.Zero)
					temp = MathX.Cross(normal, new float3(normal.z, -normal.x, normal.y));

				tangent = MathX.Cross(temp, normal).Normalized;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float3 Cross(in float3 a, in float3 b)
			{
				return new float3(
					a.y * b.z - a.z * b.y,
					a.z * b.x - a.x * b.z,
					a.x * b.y - a.y * b.x);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float3 ReflectPoint(in float3 point, in float3 planeNormal, in float3 planePosition)
			{
				var offsetPoint = point - planePosition;
				var project = Project(offsetPoint, planeNormal);
				var reject = Reject(offsetPoint, planeNormal);

				return (reject - project) + planePosition;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float3 ReflectVector(in float3 vector, in float3 planeNormal)
			{
				var project = Project(vector, planeNormal);
				var reject = Reject(vector, planeNormal);

				return reject - project;
			}

            public static float3 LimitSwing(float3 vector, in float3 reference, float maxAngle)
            {
                var angle = MathX.Angle(vector, reference);

                if(angle <= maxAngle)
                    return vector;

                vector = vector.GetNormalized(out var length);

                return MathX.Slerp(reference, vector, (float)(maxAngle / angle)) * length;
            }

			
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static bool IsBetween(this float3 value, in float3 from, in float3 to)
			{
				return value.x.IsBetween(from.x, to.x)&&value.y.IsBetween(from.y, to.y)&&value.z.IsBetween(from.z, to.z);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float3 Lerp(in float3 from, in float3 to, float t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float3 Lerp(in float3 from, float to, float t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return new float3(to, to, to);

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float3 Lerp(float from, in float3 to, float t)
			{
				if(t <= 0)
					return new float3(from, from, from);
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			public static float3 Slerp(float3 from, in float3 to, float lerp)
			{
				var dot = Dot(from, to);

                // Break singularity when the vectors are nearly opposite of each other
                if(dot < -0.999999f)
                    from = (from + 1e-3f).Normalized;

				dot = Clamp(dot, -1, 1);

				var theta = Acos(dot)*lerp;
				var relativeVec = to - from*dot;
				relativeVec = relativeVec.Normalized;

				return ((from*Cos(theta)) + (relativeVec*Sin(theta)));
			}

            // This slerps the direction uniformly, while also lerping the magnitude
            public static float3 SlerpWithMagnitude(in float3 from, in float3 to, float lerp)
            {
                var fromDir = from.GetNormalized(out var fromMag);
                var toDir = to.GetNormalized(out var toMag);

                var newMag = MathX.LerpUnclamped(fromMag, toMag, lerp);

                // If one of the vectors is zero, just take the direction from the other vector
                // rather than slerping it
                if(MathX.Approximately(fromMag, 0))
                    return toDir * newMag;

                if(MathX.Approximately(toMag, 0))
                    return fromDir * newMag;

                return Slerp(fromDir, toDir, lerp) * newMag;
            }

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float3 ClampMagnitude(in float3 v, float maxMagnitude, float minMagnitude = 0)
			{
				var mag = v.Magnitude;

				if(mag > maxMagnitude)
					return v * (maxMagnitude / mag);

				if(mag < minMagnitude && mag > 0)
					return v * (minMagnitude / mag);

				return v;
			}

		
		}


