	{
		switch(index)
		{
							
				case 0:
					return new double3(value,y,z);				
				case 1:
					return new double3(x,value,z);				
				case 2:
					return new double3(x,y,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

