		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly double3 GetNormalized(out double magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return double3.Zero;

			var invMag = ((double)1) / magnitude;
			return ((double3)this) * invMag;
		}

		[JsonIgnore]
	    public readonly double3 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == double3.Zero)
				    return this;

				var invMag = ((double)1) / Magnitude;
			    return ((double3)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly double SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (double)x*(double)x+(double)y*(double)y+(double)z*(double)z;
		}

		[JsonIgnore]
	    public readonly double Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
		[JsonIgnore]
		public readonly bool IsNaN
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => double.IsNaN(x)||double.IsNaN(y)||double.IsNaN(z);
		}

		[JsonIgnore]
		public readonly bool IsInfinity
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => double.IsInfinity(x)||double.IsInfinity(y)||double.IsInfinity(z);
		}

		public readonly bool IsUniform(double tolerance = 0.00001f)
		{
			var delta = MathX.Min(x,y,z)*tolerance;
			
			return 
			(MathX.Abs(x - y) <= delta) && (MathX.Abs(y - z) <= delta);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly bool Approximately(in double3 v, double tolerance)
		{
			return MathX.Abs(x-v.x) < tolerance&&MathX.Abs(y-v.y) < tolerance&&MathX.Abs(z-v.z) < tolerance;
		}	

		
