	// TryParse variant

	public static bool TryParse(string s, out double3 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 3);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = double.TryParse(nums[0], out double x);
		var parsed_y = double.TryParse(nums[1], out double y);
		var parsed_z = double.TryParse(nums[2], out double z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new double3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    
