        var parsed_x = double.TryParse(nums[0], numberStyles, formatProvider, out double x);
		var parsed_y = double.TryParse(nums[1], numberStyles, formatProvider, out double y);
		var parsed_z = double.TryParse(nums[2], numberStyles, formatProvider, out double z);

        if(parsed_x && parsed_y && parsed_z)
        {
            val = new double3(x, y, z);
            return true;
        }

        val = default;
        return false;
	}

    

