			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double AvgComponent(in double3 v)
			{
				return (v.x + v.y + v.z) * double3.COMPONENT_RATIO;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double Dot(in double3 a, in double3 b)
			{
				return a.x*b.x + a.y*b.y + a.z*b.z;
			}
			 
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3 Project(in double3 a, in double3 b)
			{
				var bNorm = b.Normalized;
				return bNorm * Dot(a,bNorm);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static double3 Reject(in double3 a, in double3 b) => a - Project(a,b);

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double AngleRad(in double3 a, in double3 b)
			{
				return MathX.Acos(MathX.Clamp(MathX.Dot(a.Normalized,b.Normalized), -1, 1));
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double Angle(in double3 a, in double3 b) => AngleRad(a, b) * MathX.Rad2Deg;


            
			public static double3 AxisAligned(in double3 v)
			{
				var abs = MathX.Abs(v);

										if(abs.x > abs.y && abs.x > abs.z)
							return new double3(MathX.Sign(v.x), 0, 0);

						if(abs.y > abs.z)
							return new double3(0, MathX.Sign(v.y), 0);

						return new double3(0, 0, MathX.Sign(v.z));
								}

			
			static readonly doubleQ double_orthoX = doubleQ.AxisAngle(double3.Right, 90);
			static readonly doubleQ double_orthoY = doubleQ.AxisAngle(double3.Up, 90);

			// based on this: http://stackoverflow.com/questions/3684269/component-of-a-quaternion-rotation-around-an-axis
			public static void Orthonormals(in double3 normal, out double3 ortho0, out double3 ortho1)
			{
				var normNormal = normal.Normalized;

				var w = double_orthoX * normNormal;
				if(MathX.Dot(normal,w) > 0.6f)
					w = double_orthoY * normNormal;	
					
				ortho0 = MathX.Cross(normal, w);
				ortho1 = MathX.Cross(normal, ortho0);
			}

			public static void Orthonormalize(ref double3 normal, ref double3 tangent)
			{
				if(normal == double3.Zero)
					normal = double3.Right;
				else
					normal = normal.Normalized;

				var temp = MathX.Cross(normal, tangent);

				if(temp == double3.Zero)
					temp = MathX.Cross(normal, new double3(normal.z, -normal.x, normal.y));

				tangent = MathX.Cross(temp, normal).Normalized;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3 Cross(in double3 a, in double3 b)
			{
				return new double3(
					a.y * b.z - a.z * b.y,
					a.z * b.x - a.x * b.z,
					a.x * b.y - a.y * b.x);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3 ReflectPoint(in double3 point, in double3 planeNormal, in double3 planePosition)
			{
				var offsetPoint = point - planePosition;
				var project = Project(offsetPoint, planeNormal);
				var reject = Reject(offsetPoint, planeNormal);

				return (reject - project) + planePosition;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3 ReflectVector(in double3 vector, in double3 planeNormal)
			{
				var project = Project(vector, planeNormal);
				var reject = Reject(vector, planeNormal);

				return reject - project;
			}

            public static double3 LimitSwing(double3 vector, in double3 reference, double maxAngle)
            {
                var angle = MathX.Angle(vector, reference);

                if(angle <= maxAngle)
                    return vector;

                vector = vector.GetNormalized(out var length);

                return MathX.Slerp(reference, vector, (float)(maxAngle / angle)) * length;
            }

			
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static bool IsBetween(this double3 value, in double3 from, in double3 to)
			{
				return value.x.IsBetween(from.x, to.x)&&value.y.IsBetween(from.y, to.y)&&value.z.IsBetween(from.z, to.z);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3 Lerp(in double3 from, in double3 to, double t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3 Lerp(in double3 from, double to, double t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return new double3(to, to, to);

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3 Lerp(double from, in double3 to, double t)
			{
				if(t <= 0)
					return new double3(from, from, from);
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			public static double3 Slerp(double3 from, in double3 to, float lerp)
			{
				var dot = Dot(from, to);

                // Break singularity when the vectors are nearly opposite of each other
                if(dot < -0.999999)
                    from = (from + 1e-3f).Normalized;

				dot = Clamp(dot, -1, 1);

				var theta = Acos(dot)*lerp;
				var relativeVec = to - from*dot;
				relativeVec = relativeVec.Normalized;

				return ((from*Cos(theta)) + (relativeVec*Sin(theta)));
			}

            // This slerps the direction uniformly, while also lerping the magnitude
            public static double3 SlerpWithMagnitude(in double3 from, in double3 to, float lerp)
            {
                var fromDir = from.GetNormalized(out var fromMag);
                var toDir = to.GetNormalized(out var toMag);

                var newMag = MathX.LerpUnclamped(fromMag, toMag, lerp);

                // If one of the vectors is zero, just take the direction from the other vector
                // rather than slerping it
                if(MathX.Approximately(fromMag, 0))
                    return toDir * newMag;

                if(MathX.Approximately(toMag, 0))
                    return fromDir * newMag;

                return Slerp(fromDir, toDir, lerp) * newMag;
            }

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double3 ClampMagnitude(in double3 v, double maxMagnitude, double minMagnitude = 0)
			{
				var mag = v.Magnitude;

				if(mag > maxMagnitude)
					return v * (maxMagnitude / mag);

				if(mag < minMagnitude && mag > 0)
					return v * (minMagnitude / mag);

				return v;
			}

					public static double3 Lerp(in double3 from, in double3 to, float t)
			{
				return Lerp(from, to, (double)t);
			}
			
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
