            public static bool4 False => new bool4(false,false,false,false);
	    public static bool4 True => new bool4(true,true,true,true);

		
    
    
	

	public readonly byte flags;
        public readonly bool x => (flags & (1<<0)) != 0;
            public readonly bool y => (flags & (1<<1)) != 0;
            public readonly bool z => (flags & (1<<2)) != 0;
            public readonly bool w => (flags & (1<<3)) != 0;
                         

	public readonly bool this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				case 3: return w;
				
				default: return default;
			}
		}
	}

    public readonly bool GetElement(int index) => this[index];

    public readonly bool GetElement(Axis4D axis) => this[(int)axis];

	public bool4 SetComponent(bool value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new bool4(value,y,z,w);				
				case 1:
					return new bool4(x,value,z,w);				
				case 2:
					return new bool4(x,y,value,w);				
				case 3:
					return new bool4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public bool4 SetX(bool value) => SetComponent(value, 0);

                public bool4 SetY(bool value) => SetComponent(value, 1);

                public bool4 SetZ(bool value) => SetComponent(value, 2);

                public bool4 SetW(bool value) => SetComponent(value, 3);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    int trueCount = 0;
            int falseCount = 0;

            for(int i = 0; i < 4; i++)
            {
                if(this[i])
                    trueCount++;
                else
                    falseCount++;
            }

            if(trueCount >= falseCount)
                return new bool4(true,true,true,true);
            else
                return new bool4(false,false,false,false);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new bool4(c,c,c,c);
    }

