	public static bool4 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new bool4( bool.Parse(nums[0]), bool.Parse(nums[1]), bool.Parse(nums[2]), bool.Parse(nums[3]));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out bool4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = bool.TryParse(nums[0], out bool x);
		var parsed_y = bool.TryParse(nums[1], out bool y);
		var parsed_z = bool.TryParse(nums[2], out bool z);
		var parsed_w = bool.TryParse(nums[3], out bool w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new bool4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    

