		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				case 3: return w;
				
				default: return default;
			}
		}
	}

    public readonly byte GetElement(int index) => this[index];

    public readonly byte GetElement(Axis4D axis) => this[(int)axis];

	public byte4 SetComponent(byte value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new byte4(value,y,z,w);				
				case 1:
					return new byte4(x,value,z,w);				
				case 2:
					return new byte4(x,y,value,w);				
				case 3:
					return new byte4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public byte4 SetX(byte value) => SetComponent(value, 0);

                public byte4 SetY(byte value) => SetComponent(value, 1);

                public byte4 SetZ(byte value) => SetComponent(value, 2);

                public byte4 SetW(byte value) => SetComponent(value, 3);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (byte)MathX.AvgComponent(this);
            return new byte4(c,c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new byte4(c,c,c,c);
    }

