    }

    
	public static byte4 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new byte4( byte.Parse(nums[0]), byte.Parse(nums[1]), byte.Parse(nums[2]), byte.Parse(nums[3]));
	}

    
	public static byte4 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new byte4( byte.Parse(nums[0], provider), byte.Parse(nums[1], provider), byte.Parse(nums[2], provider), byte.Parse(nums[3], provider));
	}

	public static byte4 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new byte4( byte.Parse(nums[0], style), byte.Parse(nums[1], style), byte.Parse(nums[2], style), byte.Parse(nums[3], style));
	}

	public static byte4 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new byte4( byte.Parse(nums[0], style, provider), byte.Parse(nums[1], style, provider), byte.Parse(nums[2], style, provider), byte.Parse(nums[3], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out byte4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = byte.TryParse(nums[0], out byte x);
		var parsed_y = byte.TryParse(nums[1], out byte y);
		var parsed_z = byte.TryParse(nums[2], out byte z);
		var parsed_w = byte.TryParse(nums[3], out byte w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new byte4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out byte4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = byte.TryParse(nums[0], numberStyles, formatProvider, out byte x);
		var parsed_y = byte.TryParse(nums[1], numberStyles, formatProvider, out byte y);
		var parsed_z = byte.TryParse(nums[2], numberStyles, formatProvider, out byte z);
		var parsed_w = byte.TryParse(nums[3], numberStyles, formatProvider, out byte w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new byte4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    

