public static class Byte4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in byte4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static byte4 Read4D_Byte(this BinaryReader br)
	{
        		return new byte4( br.ReadByte(),  br.ReadByte(),  br.ReadByte(),  br.ReadByte() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static byte4 Select(this bool4 mask, in byte4 onTrue, in byte4 onFalse) => new byte4(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z, mask.w ? onTrue.w : onFalse.w);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static byte MinComponent(in byte4 v)
	{
		return Min(v.x,v.y,v.z,v.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static byte MaxComponent(in byte4 v)
	{
		return Max(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in byte4 v)
	{
		return MaxIndex(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static byte4 Min(params byte4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static byte4 Max(params byte4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in byte4 a, in byte4 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z)&&MathX.Approximately(a.w, b.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in byte4 a, in byte4 b, byte epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon)&&MathX.Approximately(a.w, b.w, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static byte DistanceSqr(in byte4 a, in byte4 b)
		{
			return (byte)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z))+((a.w-b.w)*(a.w-b.w)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in byte4 a, in byte4 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static byte4 Lerp(in byte4 from, in byte4 to, float lerp)
			{
				return new byte4( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp),Lerp(from.z, to.z, lerp),Lerp(from.w, to.w, lerp));
			}

            public static byte4 LerpUnclamped(in byte4 from, in byte4 to, float lerp)
			{
				return new byte4( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp),LerpUnclamped(from.z, to.z, lerp),LerpUnclamped(from.w, to.w, lerp));
			}
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct ushort4 : IVector<ushort>, IEquatable<ushort4>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 4;
    public static readonly Type BASE_TYPE = typeof(ushort);
	public const string BASE_TYPENAME = "System.UInt16";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const ushort COMPONENT_RATIO = 1 / (ushort)4;

	public static ushort4 Zero => new ushort4(0,0,0,0);
	public static ushort4 One => new ushort4(1,1,1,1);

		public static ushort4 MinValue => new ushort4(ushort.MinValue,ushort.MinValue,ushort.MinValue,ushort.MinValue);
		public static ushort4 MaxValue => new ushort4(ushort.MaxValue,ushort.MaxValue,ushort.MaxValue,ushort.MaxValue);

    
    
	

			        public readonly ushort x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ushort X => x;

	    		        public readonly ushort y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ushort Y => y;

	    		        public readonly ushort z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ushort Z => z;

	    		        public readonly ushort w;

				[JsonPropertyName("w")]
				[JsonProperty(PropertyName = "w")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ushort W => w;

	                 

	public readonly ushort this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				case 3: return w;
				
				default: return default;
			}
		}
	}

    public readonly ushort GetElement(int index) => this[index];

    public readonly ushort GetElement(Axis4D axis) => this[(int)axis];

	public ushort4 SetComponent(ushort value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new ushort4(value,y,z,w);				
				case 1:
					return new ushort4(x,value,z,w);				
				case 2:
					return new ushort4(x,y,value,w);				
				case 3:
					return new ushort4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public ushort4 SetX(ushort value) => SetComponent(value, 0);

                public ushort4 SetY(ushort value) => SetComponent(value, 1);

                public ushort4 SetZ(ushort value) => SetComponent(value, 2);

                public ushort4 SetW(ushort value) => SetComponent(value, 3);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (ushort)MathX.AvgComponent(this);
            return new ushort4(c,c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new ushort4(c,c,c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(ushort);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
