	{
    
				        this.x = x;
		    		        this.y = y;
		    		        this.z = z;
		    		        this.w = w;
		    	}

	public ushort4(ushort4 xyzw)
	{
        this = xyzw;
	}

	
	
		public ushort4(in ushort2 xy, ushort z, ushort w) : this(xy.x, xy.y, z, w)
		{
		}

