		{
		}

		public ushort4(in ushort2 xy, in ushort2 zw) : this(xy.x, xy.y, zw.x, zw.y)
		{
		}

		public ushort4(in ushort3 xyz, ushort w) : this(xyz.x, xyz.y, xyz.z, w)
		{
