	}

    
	// TryParse variant

	public static bool TryParse(string s, out ushort4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ushort.TryParse(nums[0], out ushort x);
		var parsed_y = ushort.TryParse(nums[1], out ushort y);
		var parsed_z = ushort.TryParse(nums[2], out ushort z);
		var parsed_w = ushort.TryParse(nums[3], out ushort w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new ushort4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out ushort4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ushort.TryParse(nums[0], numberStyles, formatProvider, out ushort x);
		var parsed_y = ushort.TryParse(nums[1], numberStyles, formatProvider, out ushort y);
		var parsed_z = ushort.TryParse(nums[2], numberStyles, formatProvider, out ushort z);
		var parsed_w = ushort.TryParse(nums[3], numberStyles, formatProvider, out ushort w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new ushort4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    

