		[MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly ushort4 Mask(bool4 mask, ushort masked = default(ushort)) => new ushort4(mask.x ? x : masked, mask.y ? y : masked, mask.z ? z : masked, mask.w ? w : masked);

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
        public readonly ushort4 Mask(bool4 mask, in ushort4 masked) => new ushort4(mask.x ? x : masked.x, mask.y ? y : masked.y, mask.z ? z : masked.z, mask.w ? w : masked.w);

        
