public static class Ushort4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in ushort4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static ushort4 Read4D_UInt16(this BinaryReader br)
	{
        		return new ushort4( br.ReadUInt16(),  br.ReadUInt16(),  br.ReadUInt16(),  br.ReadUInt16() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static ushort4 Select(this bool4 mask, in ushort4 onTrue, in ushort4 onFalse) => new ushort4(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z, mask.w ? onTrue.w : onFalse.w);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort MinComponent(in ushort4 v)
	{
		return Min(v.x,v.y,v.z,v.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort MaxComponent(in ushort4 v)
	{
		return Max(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in ushort4 v)
	{
		return MaxIndex(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort4 Min(params ushort4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static ushort4 Max(params ushort4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in ushort4 a, in ushort4 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z)&&MathX.Approximately(a.w, b.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in ushort4 a, in ushort4 b, ushort epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon)&&MathX.Approximately(a.w, b.w, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static ushort DistanceSqr(in ushort4 a, in ushort4 b)
		{
			return (ushort)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z))+((a.w-b.w)*(a.w-b.w)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in ushort4 a, in ushort4 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

