	{
		switch(index)
		{
							
				case 0:
					return new uint4(value,y,z,w);				
				case 1:
					return new uint4(x,value,z,w);				
				case 2:
					return new uint4(x,y,value,w);				
				case 3:
					return new uint4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

