		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float4 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float4.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float4)this) * invMag;
		}

		[JsonIgnore]
