	// TryParse variant

	public static bool TryParse(string s, out uint4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = uint.TryParse(nums[0], out uint x);
		var parsed_y = uint.TryParse(nums[1], out uint y);
		var parsed_z = uint.TryParse(nums[2], out uint z);
		var parsed_w = uint.TryParse(nums[3], out uint w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new uint4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    
