public static class Uint4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in uint4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static uint4 Read4D_UInt32(this BinaryReader br)
	{
        		return new uint4( br.ReadUInt32(),  br.ReadUInt32(),  br.ReadUInt32(),  br.ReadUInt32() ); 	}
}


