{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static uint4 Select(this bool4 mask, in uint4 onTrue, in uint4 onFalse) => new uint4(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z, mask.w ? onTrue.w : onFalse.w);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint MinComponent(in uint4 v)
	{
		return Min(v.x,v.y,v.z,v.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static uint MaxComponent(in uint4 v)
	{
		return Max(v.x,v.y,v.z,v.w);
	}

