[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct ulong4 : IVector<ulong>, IEquatable<ulong4>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 4;
    public static readonly Type BASE_TYPE = typeof(ulong);
	public const string BASE_TYPENAME = "System.UInt64";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const ulong COMPONENT_RATIO = 1 / (ulong)4;

	public static ulong4 Zero => new ulong4(0,0,0,0);
	public static ulong4 One => new ulong4(1,1,1,1);

		public static ulong4 MinValue => new ulong4(ulong.MinValue,ulong.MinValue,ulong.MinValue,ulong.MinValue);
		public static ulong4 MaxValue => new ulong4(ulong.MaxValue,ulong.MaxValue,ulong.MaxValue,ulong.MaxValue);

    
    
	

			        public readonly ulong x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong X => x;

	    		        public readonly ulong y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong Y => y;

	    		        public readonly ulong z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong Z => z;

	    		        public readonly ulong w;

				[JsonPropertyName("w")]
				[JsonProperty(PropertyName = "w")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly ulong W => w;

	                 

	public readonly ulong this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				case 3: return w;
				
				default: return default;
			}
		}
	}

    public readonly ulong GetElement(int index) => this[index];

    public readonly ulong GetElement(Axis4D axis) => this[(int)axis];

	public ulong4 SetComponent(ulong value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new ulong4(value,y,z,w);				
				case 1:
					return new ulong4(x,value,z,w);				
				case 2:
					return new ulong4(x,y,value,w);				
				case 3:
					return new ulong4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public ulong4 SetX(ulong value) => SetComponent(value, 0);

                public ulong4 SetY(ulong value) => SetComponent(value, 1);

                public ulong4 SetZ(ulong value) => SetComponent(value, 2);

                public ulong4 SetW(ulong value) => SetComponent(value, 3);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (ulong)MathX.AvgComponent(this);
            return new ulong4(c,c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new ulong4(c,c,c,c);
    }

