	public static ulong4 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new ulong4( ulong.Parse(nums[0], style, provider), ulong.Parse(nums[1], style, provider), ulong.Parse(nums[2], style, provider), ulong.Parse(nums[3], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out ulong4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ulong.TryParse(nums[0], out ulong x);
		var parsed_y = ulong.TryParse(nums[1], out ulong y);
		var parsed_z = ulong.TryParse(nums[2], out ulong z);
		var parsed_w = ulong.TryParse(nums[3], out ulong w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new ulong4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out ulong4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = ulong.TryParse(nums[0], numberStyles, formatProvider, out ulong x);
		var parsed_y = ulong.TryParse(nums[1], numberStyles, formatProvider, out ulong y);
		var parsed_z = ulong.TryParse(nums[2], numberStyles, formatProvider, out ulong z);
		var parsed_w = ulong.TryParse(nums[3], numberStyles, formatProvider, out ulong w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new ulong4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    

