public static class Ulong4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in ulong4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static ulong4 Read4D_UInt64(this BinaryReader br)
	{
        		return new ulong4( br.ReadUInt64(),  br.ReadUInt64(),  br.ReadUInt64(),  br.ReadUInt64() ); 	}
}


