public static class Sbyte4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in sbyte4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static sbyte4 Read4D_SByte(this BinaryReader br)
	{
        		return new sbyte4( br.ReadSByte(),  br.ReadSByte(),  br.ReadSByte(),  br.ReadSByte() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static sbyte4 Select(this bool4 mask, in sbyte4 onTrue, in sbyte4 onFalse) => new sbyte4(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z, mask.w ? onTrue.w : onFalse.w);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static sbyte MinComponent(in sbyte4 v)
	{
		return Min(v.x,v.y,v.z,v.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static sbyte MaxComponent(in sbyte4 v)
	{
		return Max(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in sbyte4 v)
	{
		return MaxIndex(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static sbyte4 Min(params sbyte4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static sbyte4 Max(params sbyte4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in sbyte4 a, in sbyte4 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z)&&MathX.Approximately(a.w, b.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in sbyte4 a, in sbyte4 b, sbyte epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon)&&MathX.Approximately(a.w, b.w, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static sbyte DistanceSqr(in sbyte4 a, in sbyte4 b)
		{
			return (sbyte)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z))+((a.w-b.w)*(a.w-b.w)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in sbyte4 a, in sbyte4 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static sbyte4 Lerp(in sbyte4 from, in sbyte4 to, float lerp)
			{
				return new sbyte4( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp),Lerp(from.z, to.z, lerp),Lerp(from.w, to.w, lerp));
			}

            public static sbyte4 LerpUnclamped(in sbyte4 from, in sbyte4 to, float lerp)
			{
				return new sbyte4( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp),LerpUnclamped(from.z, to.z, lerp),LerpUnclamped(from.w, to.w, lerp));
			}
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct short4 : IVector<short>, IEquatable<short4>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 4;
    public static readonly Type BASE_TYPE = typeof(short);
	public const string BASE_TYPENAME = "System.Int16";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const short COMPONENT_RATIO = 1 / (short)4;

	public static short4 Zero => new short4(0,0,0,0);
	public static short4 One => new short4(1,1,1,1);

		public static short4 MinValue => new short4(short.MinValue,short.MinValue,short.MinValue,short.MinValue);
		public static short4 MaxValue => new short4(short.MaxValue,short.MaxValue,short.MaxValue,short.MaxValue);

    
    
	

			        public readonly short x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly short X => x;

	    		        public readonly short y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly short Y => y;

	    		        public readonly short z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly short Z => z;

	    		        public readonly short w;

				[JsonPropertyName("w")]
				[JsonProperty(PropertyName = "w")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly short W => w;

	                 

	public readonly short this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				case 3: return w;
				
				default: return default;
			}
		}
	}

    public readonly short GetElement(int index) => this[index];

    public readonly short GetElement(Axis4D axis) => this[(int)axis];

	public short4 SetComponent(short value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new short4(value,y,z,w);				
				case 1:
					return new short4(x,value,z,w);				
				case 2:
					return new short4(x,y,value,w);				
				case 3:
					return new short4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public short4 SetX(short value) => SetComponent(value, 0);

                public short4 SetY(short value) => SetComponent(value, 1);

                public short4 SetZ(short value) => SetComponent(value, 2);

                public short4 SetW(short value) => SetComponent(value, 3);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (short)MathX.AvgComponent(this);
            return new short4(c,c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new short4(c,c,c,c);
    }

