	public static short4 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new short4( short.Parse(nums[0]), short.Parse(nums[1]), short.Parse(nums[2]), short.Parse(nums[3]));
	}

    
