	}

    
	// TryParse variant

	public static bool TryParse(string s, out short4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = short.TryParse(nums[0], out short x);
		var parsed_y = short.TryParse(nums[1], out short y);
		var parsed_z = short.TryParse(nums[2], out short z);
		var parsed_w = short.TryParse(nums[3], out short w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new short4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out short4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = short.TryParse(nums[0], numberStyles, formatProvider, out short x);
		var parsed_y = short.TryParse(nums[1], numberStyles, formatProvider, out short y);
		var parsed_z = short.TryParse(nums[2], numberStyles, formatProvider, out short z);
		var parsed_w = short.TryParse(nums[3], numberStyles, formatProvider, out short w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new short4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    

