public static class Short4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in short4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static short4 Read4D_Int16(this BinaryReader br)
	{
        		return new short4( br.ReadInt16(),  br.ReadInt16(),  br.ReadInt16(),  br.ReadInt16() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static short4 Select(this bool4 mask, in short4 onTrue, in short4 onFalse) => new short4(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z, mask.w ? onTrue.w : onFalse.w);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short MinComponent(in short4 v)
	{
		return Min(v.x,v.y,v.z,v.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short MaxComponent(in short4 v)
	{
		return Max(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in short4 v)
	{
		return MaxIndex(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short4 Min(params short4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static short4 Max(params short4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in short4 a, in short4 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z)&&MathX.Approximately(a.w, b.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in short4 a, in short4 b, short epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon)&&MathX.Approximately(a.w, b.w, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static short DistanceSqr(in short4 a, in short4 b)
		{
			return (short)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z))+((a.w-b.w)*(a.w-b.w)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in short4 a, in short4 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
	
			public static short4 Lerp(in short4 from, in short4 to, float lerp)
			{
				return new short4( Lerp(from.x, to.x, lerp),Lerp(from.y, to.y, lerp),Lerp(from.z, to.z, lerp),Lerp(from.w, to.w, lerp));
			}

            public static short4 LerpUnclamped(in short4 from, in short4 to, float lerp)
			{
				return new short4( LerpUnclamped(from.x, to.x, lerp),LerpUnclamped(from.y, to.y, lerp),LerpUnclamped(from.z, to.z, lerp),LerpUnclamped(from.w, to.w, lerp));
			}
		}


[JsonObject(MemberSerialization = MemberSerialization.OptIn)]
public readonly struct int4 : IVector<int>, IEquatable<int4>, IFormattable , INumericVector
{
	public const int DIMENSIONS = 4;
    public static readonly Type BASE_TYPE = typeof(int);
	public const string BASE_TYPENAME = "System.Int32";

	[JsonIgnore]
	public int Dimensions => DIMENSIONS;

    	public const int COMPONENT_RATIO = 1 / (int)4;

	public static int4 Zero => new int4(0,0,0,0);
	public static int4 One => new int4(1,1,1,1);

		public static int4 MinValue => new int4(int.MinValue,int.MinValue,int.MinValue,int.MinValue);
		public static int4 MaxValue => new int4(int.MaxValue,int.MaxValue,int.MaxValue,int.MaxValue);

    
    
	

			        public readonly int x;

				[JsonPropertyName("x")]
				[JsonProperty(PropertyName = "x")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int X => x;

	    		        public readonly int y;

				[JsonPropertyName("y")]
				[JsonProperty(PropertyName = "y")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int Y => y;

	    		        public readonly int z;

				[JsonPropertyName("z")]
				[JsonProperty(PropertyName = "z")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int Z => z;

	    		        public readonly int w;

				[JsonPropertyName("w")]
				[JsonProperty(PropertyName = "w")]
				[DebuggerBrowsable(DebuggerBrowsableState.Never)]
				public readonly int W => w;

	                 

	public readonly int this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				case 3: return w;
				
				default: return default;
			}
		}
	}

    public readonly int GetElement(int index) => this[index];

    public readonly int GetElement(Axis4D axis) => this[(int)axis];

	public int4 SetComponent(int value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new int4(value,y,z,w);				
				case 1:
					return new int4(x,value,z,w);				
				case 2:
					return new int4(x,y,value,w);				
				case 3:
					return new int4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public int4 SetX(int value) => SetComponent(value, 0);

                public int4 SetY(int value) => SetComponent(value, 1);

                public int4 SetZ(int value) => SetComponent(value, 2);

                public int4 SetW(int value) => SetComponent(value, 3);

        
	public readonly object GetBoxedElement(int n) => this[n];

    public readonly object GetWithElementsAveraged()
    {
                    var c = (int)MathX.AvgComponent(this);
            return new int4(c,c,c,c);
                }

    public readonly object GetWithAllElementsSetTo(int n)
    {
        var c = this[n];
        return new int4(c,c,c,c);
    }

	[JsonIgnore]
	public readonly Type ElementType => typeof(int);

#region CONSTRUCTORS

    
	[System.Text.Json.Serialization.JsonConstructor]
	[Newtonsoft.Json.JsonConstructor]
	public int4(int x = default(int), int y = default(int), int z = default(int), int w = default(int))
	{
    
				        this.x = x;
		    		        this.y = y;
		    		        this.z = z;
		    		        this.w = w;
		    	}

	public int4(int4 xyzw)
	{
        this = xyzw;
	}

	
	
		public int4(in int2 xy, int z, int w) : this(xy.x, xy.y, z, w)
		{
		}

		public int4(int x, in int2 yz, int w) : this(x, yz.x, yz.y, w)
		{
		}

		public int4(int x, int y, in int2 zw) : this(x, y, zw.x, zw.y)
		{
		}

		public int4(in int2 xy, in int2 zw) : this(xy.x, xy.y, zw.x, zw.y)
		{
		}

		public int4(in int3 xyz, int w) : this(xyz.x, xyz.y, xyz.z, w)
		{
		}

		public int4(int x, in int3 yzw) : this(x, yzw.x, yzw.y, yzw.z)
		{
		}

		
#endregion

	
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float4 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float4.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float4)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float4 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float4.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float4)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y+(float)z*(float)z+(float)w*(float)w;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider)+ $"{separator} " + z.ToString(provider)+ $"{separator} " + w.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

