	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat)+ $"{separator} " + z.ToString(elementFormat)+ $"{separator} " + w.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider)+ $"{separator} " + z.ToString(elementFormat, provider)+ $"{separator} " + w.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "int4"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral() + ", " + z.ToCodeLiteral() + ", " + w.ToCodeLiteral()})";
    }

    
	public static int4 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new int4( int.Parse(nums[0]), int.Parse(nums[1]), int.Parse(nums[2]), int.Parse(nums[3]));
	}

    
	public static int4 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new int4( int.Parse(nums[0], provider), int.Parse(nums[1], provider), int.Parse(nums[2], provider), int.Parse(nums[3], provider));
	}

	public static int4 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new int4( int.Parse(nums[0], style), int.Parse(nums[1], style), int.Parse(nums[2], style), int.Parse(nums[3], style));
	}

	public static int4 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new int4( int.Parse(nums[0], style, provider), int.Parse(nums[1], style, provider), int.Parse(nums[2], style, provider), int.Parse(nums[3], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out int4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = int.TryParse(nums[0], out int x);
		var parsed_y = int.TryParse(nums[1], out int y);
		var parsed_z = int.TryParse(nums[2], out int z);
		var parsed_w = int.TryParse(nums[3], out int w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new int4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out int4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = int.TryParse(nums[0], numberStyles, formatProvider, out int x);
		var parsed_y = int.TryParse(nums[1], numberStyles, formatProvider, out int y);
		var parsed_z = int.TryParse(nums[2], numberStyles, formatProvider, out int z);
		var parsed_w = int.TryParse(nums[3], numberStyles, formatProvider, out int w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new int4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    

