public static class Int4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in int4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static int4 Read4D_Int32(this BinaryReader br)
	{
        		return new int4( br.ReadInt32(),  br.ReadInt32(),  br.ReadInt32(),  br.ReadInt32() ); 	}
}


public static partial class MathX
{
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static int4 Select(this bool4 mask, in int4 onTrue, in int4 onFalse) => new int4(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z, mask.w ? onTrue.w : onFalse.w);

    
	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MinComponent(in int4 v)
	{
		return Min(v.x,v.y,v.z,v.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponent(in int4 v)
	{
		return Max(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int MaxComponentIndex(in int4 v)
	{
		return MaxIndex(v.x,v.y,v.z,v.w);
	}

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int4 Min(params int4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var min = vals[0];

        for(int i = 1; i < vals.Length; i++)
            min = Min(min, vals[i]);

        return min;
    }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static int4 Max(params int4[] vals)
    {
		if(vals.Length <= 1)
			throw new ArgumentException("Invalid number of values: " + vals.Length);

        var max = vals[0];

        for(int i = 1; i < vals.Length; i++)
            max = Max(max, vals[i]);

        return max;
    }

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in int4 a, in int4 b)
	{
		return MathX.Approximately(a.x, b.x)&&MathX.Approximately(a.y, b.y)&&MathX.Approximately(a.z, b.z)&&MathX.Approximately(a.w, b.w);
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static bool Approximately(in int4 a, in int4 b, int epsilon)
	{
		return MathX.Approximately(a.x, b.x, epsilon)&&MathX.Approximately(a.y, b.y, epsilon)&&MathX.Approximately(a.z, b.z, epsilon)&&MathX.Approximately(a.w, b.w, epsilon);
	}

	#region VECTOR OPERATOR FUNCTIONS
		
		
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static int DistanceSqr(in int4 a, in int4 b)
		{
			return (int)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z))+((a.w-b.w)*(a.w-b.w)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static float Distance(in int4 a, in int4 b)
		{
			return MathX.Sqrt((float)DistanceSqr(a, b));
		}

#endregion

    
		
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				public static int4 Abs(in int4 n)
					{
						return new int4(MathX.Abs(n.x),MathX.Abs(n.y),MathX.Abs(n.z),MathX.Abs(n.w));
					}

					
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				public static int4 Clamp(in int4 vector, in int4 min, in int4 max)
					{
						return new int4(MathX.Clamp(vector.x, min.x, max.x),MathX.Clamp(vector.y, min.y, max.y),MathX.Clamp(vector.z, min.z, max.z),MathX.Clamp(vector.w, min.w, max.w));
					}

					
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				public static int4 Clamp(int vector, in int4 min, in int4 max)
					{
						return new int4(MathX.Clamp(vector, min.x, max.x),MathX.Clamp(vector, min.y, max.y),MathX.Clamp(vector, min.z, max.z),MathX.Clamp(vector, min.w, max.w));
					}

					
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
