					{
						return new int4(MathX.Clamp(vector.x, min, max.x),MathX.Clamp(vector.y, min, max.y),MathX.Clamp(vector.z, min, max.z),MathX.Clamp(vector.w, min, max.w));
					}

					
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				public static int4 Clamp(int vector, int min, in int4 max)
					{
						return new int4(MathX.Clamp(vector, min, max.x),MathX.Clamp(vector, min, max.y),MathX.Clamp(vector, min, max.z),MathX.Clamp(vector, min, max.w));
					}

					
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				public static int4 Clamp(in int4 vector, in int4 min, int max)
