					}

					
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				public static int4 Clamp(int vector, in int4 min, int max)
					{
						return new int4(MathX.Clamp(vector, min.x, max),MathX.Clamp(vector, min.y, max),MathX.Clamp(vector, min.z, max),MathX.Clamp(vector, min.w, max));
					}

					
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				public static int4 Clamp(in int4 vector, int min, int max)
					{
						return new int4(MathX.Clamp(vector.x, min, max),MathX.Clamp(vector.y, min, max),MathX.Clamp(vector.z, min, max),MathX.Clamp(vector.w, min, max));
