				[MethodImpl(MethodImplOptions.AggressiveInlining)]
				public static int4 Min(in int4 a, in int4 b)
					{
						return new int4(MathX.Min(a.x, b.x),MathX.Min(a.y, b.y),MathX.Min(a.z, b.z),MathX.Min(a.w, b.w));
					}

					
				[MethodImpl(MethodImplOptions.AggressiveInlining)]
