	public readonly long this[int n]
	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				case 3: return w;
				
				default: return default;
			}
		}
	}

    public readonly long GetElement(int index) => this[index];

    public readonly long GetElement(Axis4D axis) => this[(int)axis];

	public long4 SetComponent(long value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new long4(value,y,z,w);				
				case 1:
					return new long4(x,value,z,w);				
				case 2:
					return new long4(x,y,value,w);				
				case 3:
					return new long4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

            public long4 SetX(long value) => SetComponent(value, 0);

                public long4 SetY(long value) => SetComponent(value, 1);

                public long4 SetZ(long value) => SetComponent(value, 2);

                public long4 SetW(long value) => SetComponent(value, 3);

        
