public static class Long4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in long4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static long4 Read4D_Int64(this BinaryReader br)
	{
        		return new long4( br.ReadInt64(),  br.ReadInt64(),  br.ReadInt64(),  br.ReadInt64() ); 	}
}


