    public static long4 Select(this bool4 mask, in long4 onTrue, in long4 onFalse) => new long4(mask.x ? onTrue.x : onFalse.x, mask.y ? onTrue.y : onFalse.y, mask.z ? onTrue.z : onFalse.z, mask.w ? onTrue.w : onFalse.w);

    
