	{
		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		get
		{
			switch(n)
			{
				case 0: return x;
				case 1: return y;
				case 2: return z;
				case 3: return w;
				
				default: return default;
			}
		}
	}

    public readonly float GetElement(int index) => this[index];

    public readonly float GetElement(Axis4D axis) => this[(int)axis];

	public float4 SetComponent(float value, int index)
	{
		switch(index)
		{
							
				case 0:
					return new float4(value,y,z,w);				
				case 1:
					return new float4(x,value,z,w);				
				case 2:
					return new float4(x,y,value,w);				
				case 3:
					return new float4(x,y,z,value);			
			default: throw new Exception("Invalid vector element index");
		}
	}

