		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly float4 GetNormalized(out float magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return float4.Zero;

			var invMag = ((float)1) / magnitude;
			return ((float4)this) * invMag;
		}

		[JsonIgnore]
	    public readonly float4 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == float4.Zero)
				    return this;

				var invMag = ((float)1) / Magnitude;
			    return ((float4)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

		[JsonIgnore]
	    public readonly float SqrMagnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (float)x*(float)x+(float)y*(float)y+(float)z*(float)z+(float)w*(float)w;
		}

		[JsonIgnore]
	    public readonly float Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
		[JsonIgnore]
		public readonly bool IsNaN
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => float.IsNaN(x)||float.IsNaN(y)||float.IsNaN(z)||float.IsNaN(w);
		}

		[JsonIgnore]
		public readonly bool IsInfinity
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => float.IsInfinity(x)||float.IsInfinity(y)||float.IsInfinity(z)||float.IsInfinity(w);
		}

		public readonly bool IsUniform(float tolerance = 0.00001f)
		{
			var delta = MathX.Min(x,y,z,w)*tolerance;
			
			return 
			(MathX.Abs(x - y) <= delta) && (MathX.Abs(y - z) <= delta) && (MathX.Abs(z - w) <= delta);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly bool Approximately(in float4 v, float tolerance)
		{
			return MathX.Abs(x-v.x) < tolerance&&MathX.Abs(y-v.y) < tolerance&&MathX.Abs(z-v.z) < tolerance&&MathX.Abs(w-v.w) < tolerance;
		}	

		
	public override string ToString()
	{
		return ToString(System.Globalization.CultureInfo.InvariantCulture);
	}

	public string ToString(IFormatProvider provider)
	{
		return $"[{ToStringBase(provider)}]";
	}

	public string ToStringBase(IFormatProvider provider, string separator = ";")
	{
		return x.ToString(provider)+ $"{separator} " + y.ToString(provider)+ $"{separator} " + z.ToString(provider)+ $"{separator} " + w.ToString(provider);
	}

    
	public string ToString(string elementFormat)
	{
		return $"[{ToStringBase(elementFormat)}]";
	}

	public string ToStringBase(string elementFormat, string separator = ";")
	{
		return x.ToString(elementFormat)+ $"{separator} " + y.ToString(elementFormat)+ $"{separator} " + z.ToString(elementFormat)+ $"{separator} " + w.ToString(elementFormat);
	}

	public string ToString(string elementFormat, IFormatProvider provider)
	{
		return $"[{ToStringBase(elementFormat, provider)}]";
	}

	public string ToStringBase(string elementFormat, IFormatProvider provider, string separator = ";")
	{
		return x.ToString(elementFormat, provider)+ $"{separator} " + y.ToString(elementFormat, provider)+ $"{separator} " + z.ToString(elementFormat, provider)+ $"{separator} " + w.ToString(elementFormat, provider);
	}

    public string ToStringConstructor(string overrideType = null)
    {
        return $"new {overrideType ?? "float4"}({x.ToCodeLiteral() + ", " + y.ToCodeLiteral() + ", " + z.ToCodeLiteral() + ", " + w.ToCodeLiteral()})";
    }

    
	public static float4 Parse(string s)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new float4( float.Parse(nums[0]), float.Parse(nums[1]), float.Parse(nums[2]), float.Parse(nums[3]));
	}

    
	public static float4 Parse(string s, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new float4( float.Parse(nums[0], provider), float.Parse(nums[1], provider), float.Parse(nums[2], provider), float.Parse(nums[3], provider));
	}

	public static float4 Parse(string s, NumberStyles style)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new float4( float.Parse(nums[0], style), float.Parse(nums[1], style), float.Parse(nums[2], style), float.Parse(nums[3], style));
	}

	public static float4 Parse(string s, NumberStyles style, IFormatProvider provider)
	{
		var nums = PrimitivesUtility.ExtractElements(s, 4);

		return new float4( float.Parse(nums[0], style, provider), float.Parse(nums[1], style, provider), float.Parse(nums[2], style, provider), float.Parse(nums[3], style, provider));
	}

    
	// TryParse variant

	public static bool TryParse(string s, out float4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = float.TryParse(nums[0], out float x);
		var parsed_y = float.TryParse(nums[1], out float y);
		var parsed_z = float.TryParse(nums[2], out float z);
		var parsed_w = float.TryParse(nums[3], out float w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new float4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    
    public static bool TryParse(string s, NumberStyles numberStyles, IFormatProvider formatProvider, out float4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = float.TryParse(nums[0], numberStyles, formatProvider, out float x);
		var parsed_y = float.TryParse(nums[1], numberStyles, formatProvider, out float y);
		var parsed_z = float.TryParse(nums[2], numberStyles, formatProvider, out float z);
		var parsed_w = float.TryParse(nums[3], numberStyles, formatProvider, out float w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new float4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    

