			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float Dot(in float4 a, in float4 b)
			{
				return a.x*b.x + a.y*b.y + a.z*b.z + a.w*b.w;
			}
			 
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float4 Project(in float4 a, in float4 b)
			{
				var bNorm = b.Normalized;
				return bNorm * Dot(a,bNorm);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static float4 Reject(in float4 a, in float4 b) => a - Project(a,b);

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float AngleRad(in float4 a, in float4 b)
			{
				return MathX.Acos(MathX.Clamp(MathX.Dot(a.Normalized,b.Normalized), -1, 1));
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static float Angle(in float4 a, in float4 b) => AngleRad(a, b) * MathX.Rad2Deg;


            
			public static float4 AxisAligned(in float4 v)
			{
				var abs = MathX.Abs(v);

										if(abs.x > abs.y && abs.x > abs.z && abs.x > abs.w)
							return new float4(MathX.Sign(v.x), 0, 0, 0);

						if(abs.y > abs.z && abs.y > abs.w)
							return new float4(0, MathX.Sign(v.y), 0, 0);

						if(abs.z > abs.w)
							return new float4(0, 0, MathX.Sign(v.z), 0);

						return new float4(0, 0, 0, MathX.Sign(v.w));
								}

			
