		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly double4 GetNormalized(out double magnitude)
		{
			magnitude = Magnitude;

			if(magnitude == 0)
				return double4.Zero;

			var invMag = ((double)1) / magnitude;
			return ((double4)this) * invMag;
		}

		[JsonIgnore]
	    public readonly double4 Normalized
	    {
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
		    get
		    {
			    if(this == double4.Zero)
				    return this;

				var invMag = ((double)1) / Magnitude;
			    return ((double4)this) * invMag;
		    }
	    }

        [JsonIgnore]
	    readonly object INumericVector.Normalized => Normalized;

