		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => (double)x*(double)x+(double)y*(double)y+(double)z*(double)z+(double)w*(double)w;
		}

		[JsonIgnore]
	    public readonly double Magnitude 
		{
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			get => MathX.Sqrt(SqrMagnitude);
		}

    
	
