		public readonly bool IsUniform(double tolerance = 0.00001f)
		{
			var delta = MathX.Min(x,y,z,w)*tolerance;
			
			return 
			(MathX.Abs(x - y) <= delta) && (MathX.Abs(y - z) <= delta) && (MathX.Abs(z - w) <= delta);
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public readonly bool Approximately(in double4 v, double tolerance)
		{
			return MathX.Abs(x-v.x) < tolerance&&MathX.Abs(y-v.y) < tolerance&&MathX.Abs(z-v.z) < tolerance&&MathX.Abs(w-v.w) < tolerance;
		}	

		
