	// TryParse variant

	public static bool TryParse(string s, out double4 val)
	{
        var nums = PrimitivesUtility.ExtractElements(s, 4);

		if(nums == null)
		{
			val = default;
			return false;
		}

        var parsed_x = double.TryParse(nums[0], out double x);
		var parsed_y = double.TryParse(nums[1], out double y);
		var parsed_z = double.TryParse(nums[2], out double z);
		var parsed_w = double.TryParse(nums[3], out double w);

        if(parsed_x && parsed_y && parsed_z && parsed_w)
        {
            val = new double4(x, y, z, w);
            return true;
        }

        val = default;
        return false;
	}

    
