public static class Double4Extensions
{
	// BinaryReader/Writer extension
	public static void Write(this BinaryWriter bw, in double4 v)
	{
		 bw.Write(v.x);
			 bw.Write(v.y);
			 bw.Write(v.z);
			 bw.Write(v.w);
				}

	public static double4 Read4D_Double(this BinaryReader br)
	{
        		return new double4( br.ReadDouble(),  br.ReadDouble(),  br.ReadDouble(),  br.ReadDouble() ); 	}
}


