		{
			return (double)(((a.x-b.x)*(a.x-b.x))+((a.y-b.y)*(a.y-b.y))+((a.z-b.z)*(a.z-b.z))+((a.w-b.w)*(a.w-b.w)));
		}

		[MethodImpl(MethodImplOptions.AggressiveInlining)]
		public static double Distance(in double4 a, in double4 b)
		{
			return MathX.Sqrt((double)DistanceSqr(a, b));
		}

