			}
			 
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double4 Project(in double4 a, in double4 b)
			{
				var bNorm = b.Normalized;
				return bNorm * Dot(a,bNorm);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
            public static double4 Reject(in double4 a, in double4 b) => a - Project(a,b);

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double AngleRad(in double4 a, in double4 b)
			{
				return MathX.Acos(MathX.Clamp(MathX.Dot(a.Normalized,b.Normalized), -1, 1));
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double Angle(in double4 a, in double4 b) => AngleRad(a, b) * MathX.Rad2Deg;


            
