			{
				var abs = MathX.Abs(v);

										if(abs.x > abs.y && abs.x > abs.z && abs.x > abs.w)
							return new double4(MathX.Sign(v.x), 0, 0, 0);

						if(abs.y > abs.z && abs.y > abs.w)
							return new double4(0, MathX.Sign(v.y), 0, 0);

						if(abs.z > abs.w)
							return new double4(0, 0, MathX.Sign(v.z), 0);

						return new double4(0, 0, 0, MathX.Sign(v.w));
								}

			
			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static bool IsBetween(this double4 value, in double4 from, in double4 to)
			{
				return value.x.IsBetween(from.x, to.x)&&value.y.IsBetween(from.y, to.y)&&value.z.IsBetween(from.z, to.z)&&value.w.IsBetween(from.w, to.w);
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double4 Lerp(in double4 from, in double4 to, double t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double4 Lerp(in double4 from, double to, double t)
			{
				if(t <= 0)
					return from;
				if(t >= 1)
					return new double4(to, to, to, to);

				return from + (to - from) * t;
			}

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double4 Lerp(double from, in double4 to, double t)
			{
				if(t <= 0)
					return new double4(from, from, from, from);
				if(t >= 1)
					return to;

				return from + (to - from) * t;
			}

			public static double4 Slerp(double4 from, in double4 to, float lerp)
			{
				var dot = Dot(from, to);

                // Break singularity when the vectors are nearly opposite of each other
                if(dot < -0.999999)
                    from = (from + 1e-3f).Normalized;

				dot = Clamp(dot, -1, 1);

				var theta = Acos(dot)*lerp;
				var relativeVec = to - from*dot;
				relativeVec = relativeVec.Normalized;

				return ((from*Cos(theta)) + (relativeVec*Sin(theta)));
			}

            // This slerps the direction uniformly, while also lerping the magnitude
            public static double4 SlerpWithMagnitude(in double4 from, in double4 to, float lerp)
            {
                var fromDir = from.GetNormalized(out var fromMag);
                var toDir = to.GetNormalized(out var toMag);

                var newMag = MathX.LerpUnclamped(fromMag, toMag, lerp);

                // If one of the vectors is zero, just take the direction from the other vector
                // rather than slerping it
                if(MathX.Approximately(fromMag, 0))
                    return toDir * newMag;

                if(MathX.Approximately(toMag, 0))
                    return fromDir * newMag;

                return Slerp(fromDir, toDir, lerp) * newMag;
            }

			[MethodImpl(MethodImplOptions.AggressiveInlining)]
			public static double4 ClampMagnitude(in double4 v, double maxMagnitude, double minMagnitude = 0)
			{
				var mag = v.Magnitude;

				if(mag > maxMagnitude)
					return v * (maxMagnitude / mag);

				if(mag < minMagnitude && mag > 0)
					return v * (minMagnitude / mag);

				return v;
			}

					public static double4 Lerp(in double4 from, in double4 to, float t)
			{
				return Lerp(from, to, (double)t);
			}
			
		}



